const ASSETS={"/account.js":{"body":"async function checkSession(){try{const response=await fetch('/api/auth/me');const {user}=await response.json();if(!user){location.replace('/?auth=signin');return;}const label=document.getElementById('accountEmail');label.textContent=user.localOwner?'':user.email;label.hidden=Boolean(user.localOwner);document.getElementById('signOut').hidden=Boolean(user.localOwner);}catch{document.getElementById('accountEmail').textContent='Account unavailable';}}\ndocument.getElementById('signOut').addEventListener('click',async()=>{const button=document.getElementById('signOut');button.disabled=true;try{const response=await fetch('/api/auth/signout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error();location.replace('/');}catch{button.textContent='Retry sign out';button.disabled=false;}});\nwindow.addEventListener('pageshow',checkSession);\r\n","type":"text/javascript; charset=utf-8"},"/app.js":{"body":"'use strict';\r\nconst $=id=>document.getElementById(id), money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});\r\nconst fmt=n=>money.format(n), percent=n=>n.toFixed(1)+'%', esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\nlet positions=[],equity=10000000,source='No portfolio loaded';\r\nconst scenarios=[{name:'Market −5%',kind:'all',shock:-.05},{name:'Technology −8%',kind:'Technology',shock:-.08},{name:'Bond price −2.5%',kind:'Fixed Income',shock:-.025},{name:'Energy −10%',kind:'Energy',shock:-.10}];\r\nconst impact=s=>Risk.stress(positions,s.kind,s.shock).reduce((sum,o)=>sum+o.x,0), order=o=>Object.entries(o).sort((a,b)=>b[1]-a[1]);\r\nconst largest=()=>[...positions].sort((a,b)=>Math.abs(Risk.value(b))-Math.abs(Risk.value(a)))[0];\r\nconst pf=()=>Risk.summary(positions,equity), sectors=()=>order(Risk.totals(positions,'sector')), cps=()=>order(Risk.totals(positions,'cp'));\r\nfunction feedback(text,error=false){$('feedback').textContent=text;$('feedback').classList.toggle('error',error);$('feedback').hidden=false;}\r\nfunction alerts(){\r\n  const out=[],p=pf(),add=(level,title,text)=>out.push({level,title,text});\r\n  if(!positions.length)return out;\r\n  const old=positions.filter(p=>p.asOf&&(Date.now()-Date.parse(p.asOf))/86400000>7);if(old.length)add('warning','Stale position prices',`${old.length} positions have observations more than seven calendar days old.`);\r\n  const undated=positions.filter(p=>!p.asOf);if(undated.length)add('warning','Price observation dates missing',`${undated.length} positions have no price date. Imported values are unverified inputs.`);\r\n  if(p.gross>120)add('danger','Gross exposure exceeds limit',`${percent(p.gross)} of equity versus the 120% limit.`);\r\n  for(const [sector,value] of sectors())if(value/equity>.35)add('danger',`${sector} concentration breached`,`${percent(value/equity*100)} of equity versus the 35% sector limit.`);\r\n  for(const pos of positions)if(Math.abs(Risk.value(pos))/equity>.15)add('danger',`${pos.ticker} concentration breached`,`${percent(Math.abs(Risk.value(pos))/equity*100)} of equity versus the 15% position limit.`);\r\n  for(const [cp,value] of cps())if(value/equity>.25)add('warning',`${cp} exposure elevated`,`${percent(value/equity*100)} of equity versus the 25% counterparty limit. This is gross custody exposure, not estimated default loss.`);\r\n  for(const s of scenarios)if(impact(s)<-equity*.05)add('warning',`${s.name} exceeds stress budget`,`${fmt(-impact(s))} modeled loss versus the 5% equity budget (${fmt(equity*.05)}).`);\r\n  const slow=positions.filter(p=>Risk.exitDays(p)>1),unknown=positions.filter(p=>Risk.exitDays(p)===null);\r\n  if(slow.length)add('warning','Exit time exceeds one day',slow.map(p=>`${p.ticker}: ${Risk.exitDays(p).toFixed(2)} days`).join('; ')+', at 10% of normal ADV.');\r\n  if(unknown.length)add('warning','Liquidity data missing',`${unknown.length} positions have no average daily volume; exit time cannot be estimated.`);\r\n  if(positions.some(p=>p.cp==='Unspecified'))add('warning','Counterparty data incomplete','Unspecified positions are grouped together. Supply counterparties for meaningful custody concentration.');\r\n  return out;\r\n}\r\nfunction alertHTML(a){return `<div class=\"alert ${a.level}\"><div class=\"alert-icon\" aria-hidden=\"true\">${a.level==='danger'?'!':'△'}</div><div><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p></div></div>`;}\r\nfunction renderAlerts(){const all=alerts(),selected=$('severityFilter').value;$('alertPreview').innerHTML=all.slice(0,2).map(alertHTML).join('')||'<div class=\"empty\">No current breaches</div>';$('allAlerts').innerHTML=all.filter(a=>selected==='all'||a.level===selected).map(alertHTML).join('')||'<div class=\"empty\">No alerts at this severity</div>';}\r\nfunction renderPositions(){\r\n  const q=$('positionSearch').value.toLowerCase(),sector=$('sectorFilter').value,sort=$('positionSort').value;\r\n  const rows=positions.filter(p=>(sector==='all'||p.sector===sector)&&`${p.ticker} ${p.name} ${p.cp}`.toLowerCase().includes(q));\r\n  rows.sort((a,b)=>sort==='ticker'?a.ticker.localeCompare(b.ticker):sort==='liquidity'?(Risk.exitDays(b)??Infinity)-(Risk.exitDays(a)??Infinity):sort==='pnl'?Risk.summary([a],equity).day-Risk.summary([b],equity).day:Math.abs(Risk.value(b))-Math.abs(Risk.value(a)));\r\n  $('positionCount').textContent=`${rows.length} of ${positions.length} positions`;\r\n  $('positionRows').innerHTML=rows.map(p=>{const w=Math.abs(Risk.value(p))/equity*100,day=Risk.summary([p],equity).day,days=Risk.exitDays(p);return `<tr><td><div class=\"ticker\">${esc(p.ticker)} <span class=\"pill\">${p.side<0?'Short':'Long'}</span></div><div class=\"sub\">${esc(p.name)} · ${esc(p.sector)}</div></td><td>${fmt(Risk.value(p))}</td><td>${percent(w)}</td><td class=\"${day<0?'down':'up'}\">${fmt(day)}</td><td>${p.beta.toFixed(2)}</td><td>${days===null?'Unknown':days<.01?'&lt;0.01':days.toFixed(2)}</td><td>${esc(p.cp)}<div class=\"sub\">${esc(p.credit)} · supplied label</div></td><td><span class=\"pill ${w>15?'down':''}\">${w>15?'High':w>10?'Watch':'Normal'}</span></td></tr>`}).join('')||'<tr><td colspan=\"8\" class=\"empty\">No positions match these filters.</td></tr>';\r\n}\r\nfunction renderPosture(){\r\n  const p=pf(),cp=cps()[0],days=positions.map(Risk.exitDays),missing=days.filter(x=>x===null).length,maxDays=Math.max(0,...days.filter(x=>x!==null));\r\n  const items=[['Gross exposure',p.gross/120*100,`${percent(p.gross)} of equity / 120% limit`],['Liquidity',maxDays*100,`${maxDays.toFixed(2)} days maximum / 1 day limit${missing?`; ${missing} unknown`:''}`],['Largest position',p.largest/15*100,`${percent(p.largest)} of equity / 15% limit`],['Counterparty',cp[1]/equity/.25*100,`${esc(cp[0])}: ${percent(cp[1]/equity*100)} of equity / 25% limit`]];\r\n  $('riskPosture').innerHTML=items.map(([name,use,note])=>`<div class=\"risk-row\"><div class=\"risk-title\"><span>${name}</span><b class=\"${use>100?'down':''}\">${Math.round(use)}% of limit</b></div><div class=\"meter\"><span style=\"width:${Math.min(100,use)}%;background:var(--${use>100?'red':'green'})\"></span></div><small>${note}</small></div>`).join('');\r\n}\r\nfunction renderExplanation(){\r\n  const top=sectors()[0],pos=largest(),colors=['#64e3bd','#78adff','#ae9aff','#ffbd69','#ff898c','#8ccbd1'];\r\n  const total=sectors().reduce((s,o)=>s+o[1],0);\r\n  $('explanation').innerHTML=`<p style=\"font-size:19px;line-height:1.5;margin:0 0 12px\"><b>${esc(top[0])} is your largest sector exposure.</b></p><p class=\"notice\">${percent(top[1]/equity*100)} of equity is allocated on a gross basis. ${esc(pos.ticker)} is the largest position at ${percent(Math.abs(Risk.value(pos))/equity*100)} of equity.</p><div class=\"allocation\" aria-hidden=\"true\">${sectors().map(([n,v],i)=>`<span style=\"width:${v/total*100}%;background:${colors[i%colors.length]}\"></span>`).join('')}</div><div class=\"allocation-key\">${sectors().map(([n,v],i)=>`<div><span><i style=\"background:${colors[i%colors.length]}\"></i>${esc(n)}</span><b>${percent(v/equity*100)} of equity</b></div>`).join('')}</div><p class=\"notice\">Bar shows share of gross market value; labels use portfolio equity. Short positions count toward gross concentration.</p>`;\r\n}\r\nfunction renderStress(){\r\n  if(!positions.length){$('customLoss').textContent='—';$('stressBreakdown').textContent='Import positions to run stress.';return;}\r\n  const raw=$('shockMove').value,move=Number(raw),target=$('shockTarget').value;\r\n  if(raw===''||!Number.isFinite(move)||move< -100||move>100){feedback('Enter a shock between −100% and +100%.',true);return;}\r\n  const result=Risk.stress(positions,target,move/100),total=result.reduce((s,o)=>s+o.x,0),max=Math.max(1,...result.map(o=>Math.abs(o.x)));\r\n  $('customLoss').textContent=`${fmt(total)} (${percent(total/equity*100)})`;$('customLoss').className=total<0?'down':'up';\r\n  $('stressBreakdown').innerHTML=result.filter(o=>o.x!==0).sort((a,b)=>Math.abs(b.x)-Math.abs(a.x)).map(o=>`<div class=\"breakdown-row\"><span>${esc(o.p.ticker)}</span><div class=\"breakdown-track\"><span style=\"width:${Math.abs(o.x)/max*100}%;background:var(--${o.x<0?'red':'green'})\"></span></div><b class=\"${o.x<0?'down':'up'}\">${fmt(o.x)}</b></div>`).join('')||'<p class=\"notice\">No modeled impact for this selection.</p>';\r\n}\r\nfunction renderSurvival(){\r\n  const worst=Math.min(0,...scenarios.map(impact)),loss=-worst,remaining=equity-loss;\r\n  $('survival').innerHTML=`<p>Largest modeled loss: <b class=\"down\">${fmt(loss)}</b></p><p class=\"notice\">Across the four predefined scenarios, equity remaining is <b>${fmt(remaining)}</b>.</p><div class=\"risk-row\"><div class=\"risk-title\"><span>Loss / equity</span><b>${percent(loss/equity*100)}</b></div><div class=\"meter\"><span style=\"width:${Math.min(100,loss/equity*100)}%;background:var(--red)\"></span></div></div><p class=\"notice\">${remaining>0?`Recovering this loss requires a ${percent(loss/remaining*100)} gain on the remaining equity.`:'Modeled loss exhausts equity; a recovery percentage is not meaningful.'}</p><p class=\"notice\">These scenarios are illustrative, not a maximum-loss bound. Liquidity, financing costs, nonlinear payoffs and changing correlations are excluded.</p>`;\r\n}\r\nfunction refreshSelectors(){for(const id of ['sectorFilter','shockTarget']){const select=$(id),old=select.value;select.replaceChildren(new Option(id==='sectorFilter'?'All sectors':'Whole portfolio','all'),...sectors().map(([s])=>new Option(s,s)));select.value=[...select.options].some(o=>o.value===old)?old:'all';}}\r\nfunction render(){\r\n  $('portfolioEmpty').innerHTML=positions.length?'':'<div class=\"portfolio-empty\"><h2>Load a portfolio to begin</h2><p>Import your positions, set portfolio equity, and review source dates. Government monitoring uses official public data independently.</p><p class=\"notice\">No demonstration holdings are loaded automatically. Licensed connections are configured under Data connections.</p></div>';\r\n  document.querySelectorAll('#overview > .grid-2').forEach(x=>x.hidden=!positions.length);\r\n  if(!positions.length){$('metrics').innerHTML='';$('sourceLabel').textContent=source;renderPositions();renderAlerts();renderStress();$('scenarioCards').innerHTML='';$('survival').textContent='Import positions to calculate scenario losses.';return;}\r\n\r\n  const p=pf();$('sourceLabel').textContent=source;\r\n  $('metrics').innerHTML=[['Portfolio equity',fmt(equity),'User-supplied capital',''],[\"Day P&L\",fmt(p.day),'From supplied price changes',p.day<0?'down':'up'],['Gross exposure',percent(p.gross),'Limit 120%',p.gross>120?'down':''],['Net exposure',percent(p.net),'Signed value / equity',''],['Largest position',percent(p.largest),'Limit 15%',p.largest>15?'down':'']].map(x=>`<article class=\"card metric\"><label>${x[0]}</label><strong class=\"${x[3]}\">${x[1]}</strong><small>${x[2]}</small></article>`).join('');\r\n  const max=Math.max(1,...scenarios.map(s=>Math.abs(impact(s))));$('scenarioChart').innerHTML=scenarios.map(s=>{const x=impact(s);return `<div><div class=\"impact-label\"><span>${s.name}</span><b class=\"${x<0?'down':'up'}\">${fmt(x)}</b></div><div class=\"impact-track\"><span class=\"${x>=0?'gain':''}\" style=\"width:${Math.abs(x)/max*100}%\"></span></div></div>`}).join('');\r\n  $('scenarioCards').innerHTML=scenarios.map(s=>{const x=impact(s);return `<article class=\"scenario\"><h3>${s.name}</h3><strong class=\"${x<0?'down':'up'}\">${fmt(x)}</strong><p>${percent(x/equity*100)} of equity</p></article>`}).join('');\r\n  refreshSelectors();renderPositions();renderPosture();renderExplanation();renderAlerts();renderStress();renderSurvival();\r\n}\r\nfunction show(id){const names={workspace:'Portfolio workspace',systemic:'Systemic risk controls',government:'Government monitor',exchanges:'Global market directory',connections:'Data connections',evidence:'Decision evidence',overview:'Executive dashboard',positions:'Position risk',stress:'Stress laboratory',alerts:'Risk alerts',ask:'Ask Risk',method:'Methodology'};if(!names[id])return;document.querySelector('.portfolio-bar').hidden=['workspace','systemic','government','exchanges','connections','evidence','method'].includes(id);document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>{x.classList.toggle('active',x.dataset.view===id);if(x.dataset.view===id)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('pageTitle').textContent=names[id];window.scrollTo({top:0,behavior:'instant'});}\r\nfunction download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\r\nfunction answer(q){\r\n  if(!positions.length)return 'Import a portfolio first. The government monitor has separate official-source observations.';\r\n  const low=q.toLowerCase(),p=pf(),pos=largest(),top=sectors()[0];\r\n  if(/chang|increas|yesterday|histor/.test(low))return 'This workspace contains one snapshot. It cannot establish what changed over time. Import a current portfolio to inspect its exposures.';\r\n  if(/liquid|exit|volume/.test(low)){const known=positions.filter(p=>Risk.exitDays(p)!==null).sort((a,b)=>Risk.exitDays(b)-Risk.exitDays(a)),missing=positions.length-known.length;return `${known.length?`${known[0].ticker} has the longest estimated exit time: ${Risk.exitDays(known[0]).toFixed(3)} trading days at 10% of supplied ADV.`:'No positions have supplied ADV.'} ${missing} positions have unknown exit time. Normal-volume estimates can deteriorate in stressed markets.`;}\r\n  if(/counter|broker|custod/.test(low)){const cp=cps()[0];return `${cp[0]} is the largest custody grouping at ${percent(cp[1]/equity*100)} of equity. Gross exposure is compared with a 25% illustrative limit. Supplied credit labels are unverified; no counterparty default-loss estimate is available.`;}\r\n  if(/shock|fall|stress|market/.test(low))return `A −5% whole-portfolio market move, scaled by each position's beta, produces ${fmt(impact(scenarios[0]))}. The direct −8% technology shock produces ${fmt(impact(scenarios[1]))}. Use Stress lab to choose an exact move and sector.`;\r\n  if(/largest|concentr|sector/.test(low))return `${pos.ticker} is the largest position at ${percent(Math.abs(Risk.value(pos))/equity*100)} of equity. ${top[0]} is the largest sector at ${percent(top[1]/equity*100)} on a gross basis.`;\r\n  return `Gross exposure is ${percent(p.gross)}, net exposure is ${percent(p.net)}, and calculated day P&L is ${fmt(p.day)}. ${alerts().length} alerts are active. I can summarize concentration, liquidity, counterparties and predefined stress scenarios; I cannot answer arbitrary research questions.`;\r\n}\r\nfunction ask(q){for(const [kind,text] of [['user',q],['system',answer(q)]]){const el=document.createElement('div');el.className='bubble '+kind;el.textContent=text;$('conversation').append(el)}$('askInput').value='';$('conversation').lastElementChild.scrollIntoView({block:'nearest'});}\r\ndocument.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>show(b.dataset.goto));document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));\r\n$('positionSearch').oninput=renderPositions;$('sectorFilter').onchange=renderPositions;$('positionSort').onchange=renderPositions;$('severityFilter').onchange=renderAlerts;$('runStress').onclick=renderStress;\r\n$('applyEquity').onclick=()=>{const n=Number($('equityInput').value);if(!Number.isFinite(n)||n<=0){feedback('Portfolio equity must be a positive number.',true);return}equity=n;render();feedback('Equity updated. Exposure ratios and alerts recalculated.');};\r\n$('importBtn').onclick=()=>$('csvFile').click();\r\n$('csvFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Use a CSV smaller than 2 MB.');const next=Risk.parseCSV(await file.text());positions=next;source='Imported · verify source dates';$('positionSearch').value='';$('conversation').replaceChildren();$('dataNote').textContent='Imported positions are unsaved. Use Portfolio workspace to save them on this computer. Confirm equity matches this snapshot.';render();feedback(`Imported ${next.length} positions. Check portfolio equity before interpreting risk ratios.`);document.dispatchEvent(new CustomEvent('portfolio-imported',{detail:{count:next.length}}));}catch(error){feedback(error.message+' The previous portfolio is unchanged.',true);}finally{e.target.value=''}};\r\n$('resetBtn').onclick=()=>{positions=structuredClone(samplePositions);equity=10000000;source='Demonstration · synthetic holdings';$('equityInput').value=equity;$('positionSearch').value='';$('conversation').replaceChildren();$('dataNote').textContent='Illustrative positions, not live prices. Imports stay in this tab and reset on reload.';render();feedback('Sample portfolio restored.');};\r\n$('templateBtn').onclick=()=>download('riskpulse-template.csv','ticker,name,shares,price,sector,day,beta,adv,counterparty,credit,side,currency,fx_to_usd,asof,instrument_id,mic,source\\nDEMO,Example Holding,100,50,Technology,0,1,100000,Example Broker,N/A,long,USD,1,,,,Demonstration\\n','text/csv');\r\n$('downloadBtn').onclick=()=>{const p=pf();download('riskpulse-report.txt',`RISKPulse Portfolio Report\\nGenerated: ${new Date().toISOString()}\\nSource: ${source}\\nPositions: ${positions.length}\\n\\nEquity: ${fmt(equity)}\\nGross exposure: ${percent(p.gross)}\\nNet exposure: ${percent(p.net)}\\nDay P&L: ${fmt(p.day)}\\n\\nSCENARIOS\\n${scenarios.map(s=>s.name+': '+fmt(impact(s))).join('\\n')}\\n\\nALERTS\\n${alerts().map(a=>a.title+': '+a.text).join('\\n')||'No current breaches'}\\n\\nMethod: current signed market values; whole-portfolio shocks scale by supplied beta; sector shocks apply directly. Supplied equity is the denominator. Credit labels are unverified. No live prices or historical comparison. Educational model; not investment advice.`);feedback('Portfolio report downloaded.');};\r\n$('askForm').onsubmit=e=>{e.preventDefault();const q=$('askInput').value.trim();if(q)ask(q)};\r\nif(document.modelContext?.registerTool){try{\r\n document.modelContext.registerTool({name:'read_portfolio_risk',description:'Read calculated exposures and alerts from this portfolio snapshot.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({equity,...pf(),alerts:alerts()})});\r\n document.modelContext.registerTool({name:'run_portfolio_stress',description:'Apply an exact shock between -100 and +100 percent to all positions or an existing sector.',inputSchema:{type:'object',properties:{target:{type:'string'},move_pct:{type:'number',minimum:-100,maximum:100}},required:['target','move_pct'],additionalProperties:false},execute:async input=>{if(!input||!['all',...sectors().map(s=>s[0])].includes(input.target)||!Number.isFinite(input.move_pct)||Math.abs(input.move_pct)>100)throw Error('Invalid target or move');$('shockTarget').value=input.target;$('shockMove').value=input.move_pct;renderStress();show('stress');return{target:input.target,move_pct:input.move_pct,estimated_impact:Risk.stress(positions,input.target,input.move_pct/100).reduce((s,o)=>s+o.x,0)}}});\r\n}catch{}}\r\nrender();show('government');\r\n","type":"text/javascript; charset=utf-8"},"/controls.js":{"body":"'use strict';\n(function(root){\nfunction evaluate(v){\n const bounds={depth:[0,1e15],duplicate:[0,100],withdrawal:[0,100],order:[0,1e15],inventory:[0,1e15],limit:[1,1e15],age:[0,1e9],maxAge:[1,1e9],cash:[0,1e15],margin:[0,1e15],outflows:[0,1e15]};\n for(const [k,[lo,hi]] of Object.entries(bounds))if(!Number.isFinite(v[k])||v[k]<lo||v[k]>hi)throw Error('Invalid '+k+' input.');\n const effectiveDepth=v.depth*(1-v.duplicate/100)*(1-v.withdrawal/100),fundingGap=Math.max(0,v.margin+v.outflows-v.cash);\n const checks=[['Quote freshness',v.age>v.maxAge,'Pause new orders using this feed; reconcile sequence gaps and compare independent prices before resuming.'],['Executable depth',v.order>effectiveDepth,'Reduce the proposed slice and validate firm liquidity; displayed depth may disappear before arrival.'],['Inventory capacity',v.inventory+v.order>v.limit,'Reserve outstanding orders across venues before admitting additional exposure; reconcile fills and cancel acknowledgements.'],['Funding coverage',fundingGap>0,'Escalate to treasury; confirm eligible collateral and committed funding before increasing exposure.']].map(([name,breach,action])=>({name,breach,action}));\n return {effectiveDepth,fundingGap,inventoryAfter:v.inventory+v.order,status:checks.some(c=>c.breach)?'HOLD FOR REVIEW':'WITHIN ENTERED LIMITS',checks};\n}\nroot.SystemicControls={evaluate};if(typeof module!=='undefined')module.exports=root.SystemicControls;\nif(typeof document==='undefined')return;\nconst fields=[['depth','Displayed depth (USD)',1000000],['duplicate','Assumed duplicate depth (%)',30],['withdrawal','Additional withdrawal (%)',50],['order','Proposed order (USD)',400000],['inventory','Current + reserved exposure (USD)',600000],['limit','Inventory limit (USD)',900000],['age','Quote age (ms)',150],['maxAge','Maximum quote age (ms)',100],['cash','Available cash / eligible collateral (USD)',300000],['margin','Stressed margin call (USD)',350000],['outflows','Other due outflows (USD)',50000]];\nconst policies=[\n ['Duplicate orders and ghost liquidity','Measure post-fill cancellations and deduplicate related depth. Reserve parent-order exposure across venues; cancellations release capacity only after acknowledgement.'],\n ['Latency arbitrage and adverse selection','Monitor quote age, feed sequence gaps, arrival slippage and post-fill markouts. Reject stale references; benchmark routing on executable outcomes.'],\n ['Inventory spirals and hot-potato volume','Aggregate positions and outstanding commitments across venues. Limit new exposure and participation; distinguish repeated turnover from replenishing depth.'],\n ['Crowding and liquidity commonality','Stress simultaneous withdrawal across assets and counterparties. Review common signals and correlated exits; validate portfolio liquidity using stressed volume.'],\n ['Margin tightening and fat tails','Combine price shocks, haircuts and margin calls. Maintain a tested funding plan; use historical and reverse stress scenarios alongside distribution-based models.'],\n ['Routing overload and settlement failures','Test burst traffic, reconnects, duplicate messages and late fills. Use idempotent order IDs, bounded queues, reconciliation and rehearsed failover.'],\n ['Regulatory lag and correlated cutoffs','Predefine escalation and restart criteria. Replay interacting strategies and venue outages; test kill controls and consequences of simultaneous withdrawal.'],\n ['Incentives and real-economy impact','Have the board review deferred compensation, leverage limits and long-horizon capital allocation. Map derivatives and counterparty incentives; software cannot resolve these governance choices.']\n];\nconst panel=document.createElement('section');panel.id='systemic';panel.className='view';panel.innerHTML=`<div class=\"section-head\"><div><h2>Systemic risk controls</h2><p>Assess a proposed order against liquidity, inventory and funding constraints.</p></div><span class=\"badge\">Scenario analysis</span></div><p class=\"public-note\">Inputs below are illustrative assumptions until you replace them with verified observations. These checks do not send or cancel orders. Thresholds require institution-specific approval.</p><form id=\"controlForm\" class=\"card\"><div class=\"control-fields\">${fields.map(([k,label,val])=>`<label>${label}<input class=\"text-input\" name=\"${k}\" type=\"number\" step=\"any\" min=\"${['limit','maxAge'].includes(k)?1:0}\" ${['duplicate','withdrawal'].includes(k)?'max=\"100\"':''} value=\"${val}\" required></label>`).join('')}</div><div class=\"controls\"><button class=\"btn primary\">Evaluate controls</button><button class=\"btn\" type=\"button\" id=\"controlExport\" disabled>Download assessment</button></div></form><div id=\"controlResult\" aria-live=\"polite\"></div><article class=\"card\" style=\"margin-top:16px\"><h2>Response playbooks</h2><div class=\"grid-even\">${policies.map(([title,body])=>`<div><h3>${title}</h3><p>${body}</p></div>`).join('')}</div><p class=\"notice\">Proposed operational responses, not a guarantee of market stability or a compliance determination. Live detection requires synchronized order-level feeds and broker integration.</p><p><a href=\"https://www.sec.gov/files/faq-15c-5-risk-management-controls-bd.htm\" target=\"_blank\" rel=\"noopener\">SEC market-access controls</a> · <a href=\"https://www.esma.europa.eu/sites/default/files/2026-02/ESMA74-1505669079-10311_Supervisory_Briefing_on_Algorithmic_Trading_in_the_EU.pdf\" target=\"_blank\" rel=\"noopener\">ESMA algorithmic trading supervision</a> · <a href=\"https://www.bis.org/committees/bcbs/basel-consolidated-guidelines/module/lqy/10\" target=\"_blank\" rel=\"noopener\">BIS liquidity stress guidance</a></p></article>`;\ndocument.querySelector('main').append(panel);\nconst nav=document.createElement('button');nav.textContent='Systemic risk controls';nav.dataset.view='systemic';nav.onclick=()=>show('systemic');document.querySelector('.nav').prepend(nav);\nlet snapshot=null;\ndocument.getElementById('controlForm').oninput=()=>{snapshot=null;document.getElementById('controlExport').disabled=true;document.getElementById('controlResult').textContent='Inputs changed. Evaluate controls to update results.';};\ndocument.getElementById('controlForm').onsubmit=e=>{e.preventDefault();try{const inputs=Object.fromEntries(fields.map(([k])=>[k,Number(e.target.elements[k].value)])),result=evaluate(inputs);snapshot={generatedAt:new Date().toISOString(),model:'Scenario controls v1',inputType:'User-entered assumptions; not live market telemetry',inputs,result};document.getElementById('controlResult').innerHTML=`<article class=\"card\" style=\"margin-top:16px\"><h2 class=\"${result.checks.some(c=>c.breach)?'warn':'up'}\">${result.status}</h2><p>Stressed executable depth: ${fmt(result.effectiveDepth)} · Funding shortfall: ${fmt(result.fundingGap)} · Exposure after order: ${fmt(result.inventoryAfter)}</p>${result.checks.map(c=>`<div class=\"risk-row\"><b>${c.name}: ${c.breach?'BREACH':'Within entered limit'}</b><p>${c.breach?c.action:'Continue monitoring; this check alone does not authorize trading.'}</p></div>`).join('')}<p class=\"notice\">Depth = displayed × (1 − duplicate fraction) × (1 − additional withdrawal). Exposure assumes the order increases absolute exposure. Funding gap = max(0, margin + other outflows − available resources). No price-impact forecast is calculated.</p></article>`;document.getElementById('controlExport').disabled=false;logActivity('Systemic controls evaluated',snapshot);}catch(err){document.getElementById('controlResult').textContent=err.message;}};\ndocument.getElementById('controlExport').onclick=()=>{if(snapshot)download('riskpulse-controls.json',JSON.stringify(snapshot,null,2),'application/json');};\n})(typeof globalThis!=='undefined'?globalThis:this);\n","type":"text/javascript; charset=utf-8"},"/dashboard-app.js":{"body":"\nconst fmt=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});\nconst pct=n=>`${n>=0?'+':''}${n.toFixed(1)}%`;\nlet positions=[\n {ticker:'NVDA',name:'NVIDIA',sector:'Technology',shares:12000,price:178.2,day:-2.6,beta:1.66,adv:188000000,cp:'Interactive Brokers',credit:'A',side:1},\n {ticker:'MSFT',name:'Microsoft',sector:'Technology',shares:4200,price:514.4,day:-1.1,beta:1.02,adv:21000000,cp:'Schwab',credit:'AA+',side:1},\n {ticker:'AMD',name:'Advanced Micro Devices',sector:'Technology',shares:8500,price:162.1,day:-3.8,beta:1.78,adv:52000000,cp:'Interactive Brokers',credit:'BBB+',side:1},\n {ticker:'JPM',name:'JPMorgan Chase',sector:'Financials',shares:6200,price:294.7,day:.8,beta:1.08,adv:8900000,cp:'Prime Broker A',credit:'A-',side:1},\n {ticker:'XOM',name:'Exxon Mobil',sector:'Energy',shares:10000,price:117.3,day:1.4,beta:.82,adv:16500000,cp:'Schwab',credit:'AA-',side:1},\n {ticker:'TSLA',name:'Tesla short',sector:'Consumer',shares:3500,price:426.6,day:-2.2,beta:2.08,adv:75000000,cp:'Prime Broker A',credit:'BBB',side:-1},\n {ticker:'BND',name:'Vanguard Total Bond',sector:'Fixed Income',shares:24000,price:74.1,day:.1,beta:.12,adv:7600000,cp:'Custodian B',credit:'AA',side:1}\n];\nconst equity=10000000;\nconst scenarios=[{name:'S&P 500 −5%',shock:-.05,kind:'all'},{name:'Nasdaq −8%',shock:-.08,kind:'Technology'},{name:'Rates +100 bps',shock:-.025,kind:'Fixed Income'},{name:'Oil −10%',shock:-.10,kind:'Energy'}];\nfunction value(p){return p.shares*p.price*p.side} function absValue(p){return Math.abs(value(p))}\nfunction totalLong(){return positions.filter(p=>p.side>0).reduce((s,p)=>s+value(p),0)} function totalShort(){return Math.abs(positions.filter(p=>p.side<0).reduce((s,p)=>s+value(p),0))}\nfunction portfolio(){const gross=(totalLong()+totalShort())/equity*100,net=(totalLong()-totalShort())/equity*100,day=positions.reduce((s,p)=>s+value(p)*p.day/100,0),largest=Math.max(...positions.map(p=>absValue(p)))/equity*100;return{gross,net,day,largest,value:equity+day}}\nfunction scenarioImpact(s){return positions.reduce((sum,p)=>{const applies=s.kind==='all'||p.sector===s.kind;if(!applies)return sum;const sensitivity=s.kind==='all'?p.beta:1;return sum+value(p)*s.shock*sensitivity},0)}\nfunction sectorTotals(){const x={};positions.forEach(p=>x[p.sector]=(x[p.sector]||0)+value(p));return x}\nfunction counterpartyTotals(){const x={};positions.forEach(p=>x[p.cp]=(x[p.cp]||0)+absValue(p));return x}\nfunction liquidityDays(p){return p.shares/(p.adv*.1)}\nfunction alerts(){const pf=portfolio(), sectors=sectorTotals(), cps=counterpartyTotals(), out=[];const tech=Math.abs(sectors.Technology||0)/equity*100;if(tech>35)out.push({level:'danger',title:'Technology concentration breached',text:`Technology exposure is ${tech.toFixed(1)}%, above the 35% limit. NVDA is the largest contributor.`,time:'Now'});if(pf.largest>15)out.push({level:'danger',title:'Single-name concentration breached',text:`Largest position is ${pf.largest.toFixed(1)}% of equity, above the 15% limit.`,time:'Now'});const maxCp=Object.entries(cps).sort((a,b)=>b[1]-a[1])[0];if(maxCp&&maxCp[1]/equity*100>25)out.push({level:'warning',title:'Counterparty dependency elevated',text:`${maxCp[0]} holds ${(maxCp[1]/equity*100).toFixed(1)}% of gross exposure. Review limits and exit assumptions.`,time:'3 min'});const nas=Math.abs(scenarioImpact(scenarios[1]));if(nas/equity>0.05)out.push({level:'warning',title:'Nasdaq stress loss exceeds budget',text:`The −8% technology scenario implies ${fmt.format(nas)} loss, above the 5% portfolio stress budget.`,time:'Now'});return out}\nfunction alertHTML(a){return `<div class=\"alert ${a.level}\"><div class=\"alert-icon\">${a.level==='danger'?'!':'△'}</div><div><h3>${a.title}</h3><p>${a.text}</p></div><time>${a.time}</time></div>`}\nfunction render(){const pf=portfolio(), tech=(sectorTotals().Technology||0)/equity*100, cp=Object.values(counterpartyTotals()).sort((a,b)=>b-a)[0]/equity*100;\n document.getElementById('metrics').innerHTML=[['Portfolio equity',fmt.format(equity),'Read-only calculated view',''],[\"Today's P&L\",fmt.format(pf.day),pct(pf.day/equity*100),pf.day<0?'down':'up'],['Gross exposure',pf.gross.toFixed(1)+'%','Limit 120%',pf.gross>120?'down':''],['Net exposure',pf.net.toFixed(1)+'%','Directional sensitivity',''],['Largest position',pf.largest.toFixed(1)+'%','Limit 15%',pf.largest>15?'down':'warn']].map(x=>`<article class=\"card metric\"><label>${x[0]}</label><strong class=\"${x[3]}\">${x[1]}</strong><small>${x[2]}</small></article>`).join('');\n const imp=scenarios.map(s=>scenarioImpact(s)), max=Math.max(...imp.map(Math.abs));document.getElementById('scenarioChart').innerHTML=scenarios.map((s,i)=>`<div class=\"bar ${imp[i]<0?'neg':''}\" style=\"height:${Math.max(18,Math.abs(imp[i])/max*100)}%\" title=\"${s.name}: ${fmt.format(imp[i])}\"><span>${s.name.split(' ')[0]}</span></div>`).join('');\n const posture=[['Market',Math.min(100,pf.gross/120*100),pf.gross>110?'#ffbd59':'#3de0b2',`${pf.gross.toFixed(0)}% gross / 120% limit`],['Liquidity',34,'#3de0b2','All positions < 1 day at 10% ADV'],['Credit',47,'#6aa9ff','Lowest counterparty rating A−'],['Counterparty',Math.min(100,cp/35*100),cp>25?'#ffbd59':'#3de0b2',`${cp.toFixed(1)}% at largest counterparty`]];document.getElementById('riskPosture').innerHTML=posture.map(r=>`<div class=\"risk-row\"><div class=\"risk-title\"><span>${r[0]}</span><b>${Math.round(r[1])}/100</b></div><div class=\"meter\"><span style=\"width:${r[1]}%;background:${r[2]}\"></span></div><small>${r[3]}</small></div>`).join('');\n const largest=[...positions].sort((a,b)=>absValue(b)-absValue(a))[0];document.getElementById('explanation').innerHTML=`<p style=\"font-size:18px;line-height:1.45;margin:0 0 12px\"><b>Risk is concentrated in technology and one large position.</b></p><p style=\"color:var(--muted);line-height:1.65;margin:0\">Technology represents <b style=\"color:var(--text)\">${tech.toFixed(1)}%</b> of equity. ${largest.ticker} alone contributes <b style=\"color:var(--text)\">${(absValue(largest)/equity*100).toFixed(1)}%</b>. Because the technology holdings have above-market beta, an 8% Nasdaq shock produces an estimated <b class=\"down\">${fmt.format(scenarioImpact(scenarios[1]))}</b> impact. Gross exposure remains ${pf.gross<120?'inside':'above'} its 120% limit.</p>`;\n const al=alerts();document.getElementById('alertPreview').innerHTML=al.slice(0,2).map(alertHTML).join('')||'<div class=\"empty\">No current breaches</div>';document.getElementById('allAlerts').innerHTML=al.map(alertHTML).join('')||'<div class=\"empty\">No current breaches</div>';\n document.getElementById('positionCount').textContent=`${positions.length} positions`;document.getElementById('positionRows').innerHTML=[...positions].sort((a,b)=>absValue(b)-absValue(a)).map(p=>{const w=absValue(p)/equity*100,r=w>15?'High':w>10?'Watch':'Normal';return `<tr><td><div class=\"ticker\">${p.ticker}</div><div class=\"sub\">${p.name}</div></td><td>${fmt.format(value(p))}</td><td>${w.toFixed(1)}%</td><td class=\"${p.day*p.side<0?'down':'up'}\">${fmt.format(value(p)*p.day/100)}</td><td>${p.beta.toFixed(2)}</td><td>${liquidityDays(p).toFixed(2)}</td><td>${p.cp}<div class=\"sub\">${p.credit}</div></td><td><span class=\"pill\">${r}</span></td></tr>`}).join('');\n document.getElementById('scenarioCards').innerHTML=scenarios.map(s=>{const x=scenarioImpact(s);return `<article class=\"scenario\"><h3>${s.name}</h3><strong class=\"${x<0?'down':'up'}\">${fmt.format(x)}</strong><p>${Math.abs(x/equity*100).toFixed(2)}% of portfolio equity</p></article>`}).join('');renderStress();renderSurvival();}\nfunction renderStress(){const kind=document.getElementById('shockTarget').value,shock=Number(document.getElementById('shockMove').value)/100;const impacts=positions.map(p=>({p,x:(kind==='all'||p.sector===kind)?value(p)*shock*(kind==='all'?p.beta:1):0})).filter(o=>o.x);const total=impacts.reduce((s,o)=>s+o.x,0);document.getElementById('customLoss').textContent=fmt.format(total);const max=Math.max(...impacts.map(o=>Math.abs(o.x)),1);document.getElementById('stressBreakdown').innerHTML=impacts.sort((a,b)=>Math.abs(b.x)-Math.abs(a.x)).slice(0,5).map(o=>`<div class=\"breakdown-row\"><span>${o.p.ticker}</span><div class=\"breakdown-track\"><span style=\"width:${Math.abs(o.x)/max*100}%\"></span></div><b>${fmt.format(o.x)}</b></div>`).join('')}\nfunction renderSurvival(){const worst=Math.min(...scenarios.map(s=>scenarioImpact(s))),loss=Math.abs(worst),remaining=equity-loss,recovery=loss/remaining*100;document.getElementById('survival').innerHTML=`<p style=\"font-size:14px;color:var(--muted);line-height:1.6\">Worst predefined scenario: <b style=\"color:var(--text)\">${fmt.format(worst)}</b>. Equity remaining: <b style=\"color:var(--text)\">${fmt.format(remaining)}</b>.</p><div class=\"risk-row\"><div class=\"risk-title\"><span>Stress loss / equity</span><b>${(loss/equity*100).toFixed(2)}%</b></div><div class=\"meter\"><span style=\"width:${Math.min(100,loss/equity*100*10)}%;background:var(--red)\"></span></div><small>A ${(loss/equity*100).toFixed(1)}% loss requires a ${recovery.toFixed(1)}% gain to recover.</small></div><p class=\"sub\">The manuscript principle is preserved: capital is the equipment of the laboratory; every modeled loss must remain survivable.</p>`}\ndocument.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>show(b.dataset.goto));function show(id){document.querySelectorAll('.view,.nav button').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelector(`.nav button[data-view=\"${id}\"]`).classList.add('active');document.getElementById('pageTitle').textContent={overview:'Portfolio overview',positions:'Position risk',stress:'Stress laboratory',alerts:'Risk alerts',ask:'Ask Risk',method:'Methodology'}[id];window.scrollTo({top:0,behavior:'smooth'})}\ndocument.getElementById('runStress').onclick=renderStress;document.getElementById('severityFilter').onchange=e=>{const v=e.target.value;document.getElementById('allAlerts').innerHTML=alerts().filter(a=>v==='all'||a.level===v).map(alertHTML).join('')||'<div class=\"empty\">No alerts at this severity</div>'};\ndocument.getElementById('csvFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{try{const lines=reader.result.trim().split(/\\r?\\n/),heads=lines[0].split(',').map(x=>x.trim().toLowerCase());const need=['ticker','shares','price','sector'];if(!need.every(x=>heads.includes(x)))throw Error();positions=lines.slice(1).map(line=>{const c=line.split(','),o={};heads.forEach((h,i)=>o[h]=c[i]?.trim());return{ticker:o.ticker,name:o.name||o.ticker,sector:o.sector,shares:+o.shares,price:+o.price,day:+o.day||0,beta:+o.beta||1,adv:+o.adv||1000000,cp:o.counterparty||'Imported broker',credit:o.credit||'N/A',side:(o.side||'long').toLowerCase()==='short'?-1:1}});render();alert('Positions imported successfully.');}catch{alert('CSV must include ticker, shares, price, and sector. Optional: name, day, beta, adv, counterparty, credit, side.')}};reader.readAsText(f)};\ndocument.getElementById('downloadBtn').onclick=()=>{const pf=portfolio();const text=`RISKPulse Portfolio Report\\nGenerated: ${new Date().toLocaleString()}\\n\\nEquity: ${fmt.format(equity)}\\nGross exposure: ${pf.gross.toFixed(1)}%\\nNet exposure: ${pf.net.toFixed(1)}%\\nDay P&L: ${fmt.format(pf.day)}\\n\\nAlerts:\\n${alerts().map(a=>'- '+a.title+': '+a.text).join('\\n')}\\n\\nEducational, read-only risk intelligence. Not investment advice.`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='riskpulse-report.txt';a.click();URL.revokeObjectURL(a.href)};\ndocument.getElementById('askForm').onsubmit=e=>{e.preventDefault();const input=document.getElementById('askInput'),q=input.value.trim();if(!q)return;const box=document.getElementById('conversation');box.insertAdjacentHTML('beforeend',`<div class=\"bubble user\">${q.replace(/[<>]/g,'')}</div>`);let ans,low=q.toLowerCase(),pf=portfolio(),tech=sectorTotals().Technology/equity*100;if(low.includes('liquid'))ans=`Liquidity is currently strongest in NVDA and weakest in ${[...positions].sort((a,b)=>liquidityDays(b)-liquidityDays(a))[0].ticker}. At 10% of normal daily volume, every loaded position is estimated to exit in under one trading day. This estimate can deteriorate sharply under stressed volume and wider spreads.`;else if(low.includes('counter')){const m=Object.entries(counterpartyTotals()).sort((a,b)=>b[1]-a[1])[0];ans=`The largest counterparty exposure is ${m[0]} at ${(m[1]/equity*100).toFixed(1)}% of equity-equivalent gross exposure. That is operational concentration even if the securities themselves are diversified.`}else if(low.includes('shock')||low.includes('fall')||low.includes('nasdaq'))ans=`Under the predefined Nasdaq −8% scenario, the estimated impact is ${fmt.format(scenarioImpact(scenarios[1]))}. The result is driven by technology exposure of ${tech.toFixed(1)}% and above-market beta in NVDA and AMD.`;else if(low.includes('largest')||low.includes('concentr')){const p=[...positions].sort((a,b)=>absValue(b)-absValue(a))[0];ans=`${p.ticker} is the largest position at ${(absValue(p)/equity*100).toFixed(1)}% of equity. Total technology exposure is ${tech.toFixed(1)}%, so correlated holdings make diversification weaker than the position count suggests.`}else ans=`Current gross exposure is ${pf.gross.toFixed(1)}%, net exposure is ${pf.net.toFixed(1)}%, and today's calculated P&L is ${fmt.format(pf.day)}. The main review priority is technology concentration, followed by the largest counterparty dependency.`;box.insertAdjacentHTML('beforeend',`<div class=\"bubble system\">${ans}</div>`);input.value='';box.lastElementChild.scrollIntoView({behavior:'smooth'})};\nif(document.modelContext?.registerTool){\n const lifecycle=new AbortController();\n Promise.resolve(document.modelContext.registerTool({name:'read_portfolio_risk',title:'Read portfolio risk',description:'Return the current calculated exposure, stress loss, and active risk-alert summary.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const p=portfolio();return{equity,gross_exposure_pct:+p.gross.toFixed(2),net_exposure_pct:+p.net.toFixed(2),largest_position_pct:+p.largest.toFixed(2),nasdaq_8pct_impact:scenarioImpact(scenarios[1]),alerts:alerts().map(a=>a.title)}}},{signal:lifecycle.signal})).catch(()=>{});\n Promise.resolve(document.modelContext.registerTool({name:'run_portfolio_stress',title:'Run portfolio stress',description:'Run a deterministic percentage shock against the whole portfolio or one sector and update the visible stress laboratory.',inputSchema:{type:'object',properties:{target:{type:'string',enum:['all','Technology','Financials','Energy']},move_pct:{type:'number',minimum:-30,maximum:30}},required:['target','move_pct'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['all','Technology','Financials','Energy'].includes(input.target)||typeof input.move_pct!=='number')throw new Error('Invalid stress input');document.getElementById('shockTarget').value=input.target;const supported=[-5,-10,-15,-20];const selected=supported.includes(input.move_pct)?input.move_pct:-10;document.getElementById('shockMove').value=String(selected);renderStress();show('stress');return{target:input.target,move_pct:selected,estimated_impact:document.getElementById('customLoss').textContent}}},{signal:lifecycle.signal})).catch(()=>{});\n}\nrender();\n\r\n","type":"text/javascript; charset=utf-8"},"/dashboard.html":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n  <meta charset=\"utf-8\" />\r\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\r\n  <title>RiskPulse Portfolio Intelligence</title>\r\n  <meta name=\"description\" content=\"Read-only portfolio risk intelligence for market, liquidity, credit, and counterparty exposure.\" />\r\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%23071015'/%3E%3Cpath d='M10 39h10l6-17 9 28 7-20 5 9h7' fill='none' stroke='%233de0b2' stroke-width='5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E\" />\r\n  <style>\r\n    :root{--bg:#061015;--panel:#0b171e;--panel2:#101f27;--line:#20333d;--text:#edf6f4;--muted:#8ca3aa;--green:#3de0b2;--amber:#ffbd59;--red:#ff6b6b;--blue:#6aa9ff;--radius:16px}\r\n    *{box-sizing:border-box} body{margin:0;background:linear-gradient(150deg,#061015 0%,#08151c 55%,#091017 100%);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;font-size:16px;min-height:100vh}\r\n    button,input,select{font:inherit} button{cursor:pointer}.app{display:grid;grid-template-columns:236px 1fr;min-height:100vh}.sidebar{padding:24px 18px;border-right:1px solid var(--line);background:rgba(5,14,19,.88);position:sticky;top:0;height:100vh}.brand{display:flex;gap:11px;align-items:center;margin-bottom:34px}.mark{width:36px;height:36px;border:1px solid #31515a;border-radius:11px;display:grid;place-items:center;color:var(--green);font-weight:800}.brand strong{display:block;font-size:17px}.brand span{font-size:12px;color:var(--muted)}.nav{display:grid;gap:7px}.nav button{border:0;background:transparent;color:var(--muted);text-align:left;border-radius:11px;padding:12px 13px;font-size:14px}.nav button.active,.nav button:hover{background:#12242c;color:var(--text)}.nav button.active{box-shadow:inset 3px 0 var(--green)}.sidebar-note{position:absolute;left:18px;right:18px;bottom:22px;padding:13px;border:1px solid var(--line);border-radius:12px;color:var(--muted);font-size:12px;line-height:1.5}.sidebar-note b{color:var(--green)}\r\n    main{padding:26px 30px 54px;max-width:1500px;width:100%;margin:0 auto}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.eyebrow{color:var(--green);font-size:12px;text-transform:uppercase;letter-spacing:.13em;font-weight:700}.topbar h1{font-size:26px;margin:5px 0 0;letter-spacing:-.03em}.actions{display:flex;gap:10px;align-items:center}.status{font-size:13px;color:var(--muted);padding-right:8px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);margin-right:7px}.btn{border:1px solid var(--line);background:#10212a;color:var(--text);padding:10px 14px;border-radius:10px;font-weight:650;font-size:13px}.btn:hover{border-color:#47717e}.btn.primary{background:var(--green);color:#03261e;border-color:var(--green)}input[type=file]{display:none}\r\n    .view{display:none}.view.active{display:block}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:14px}.card{background:linear-gradient(180deg,rgba(16,31,39,.94),rgba(10,23,30,.94));border:1px solid var(--line);border-radius:var(--radius);padding:17px}.metric label{display:block;color:var(--muted);font-size:12px;margin-bottom:12px}.metric strong{font-size:24px;letter-spacing:-.03em}.metric small{display:block;color:var(--muted);margin-top:8px;font-size:12px}.up{color:var(--green)}.down{color:var(--red)}.warn{color:var(--amber)}\r\n    .grid-2{display:grid;grid-template-columns:1.45fr 1fr;gap:14px;margin-top:14px}.grid-even{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}.section-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:15px}.section-head h2{font-size:16px;margin:0}.section-head p{color:var(--muted);font-size:12px;margin:5px 0 0}.badge{font-size:11px;padding:5px 8px;border-radius:999px;background:#132c2b;color:var(--green);border:1px solid #245147}.chart{height:244px;display:flex;align-items:end;gap:8px;padding:16px 4px 26px;position:relative;border-bottom:1px solid var(--line)}.bar{flex:1;border-radius:5px 5px 1px 1px;background:linear-gradient(#47e0b7,#1b876e);min-width:18px;position:relative;transition:.2s}.bar.neg{background:linear-gradient(#ff8a75,#a53b3b)}.bar span{position:absolute;bottom:-22px;left:50%;transform:translateX(-50%);font-size:10px;color:var(--muted)}.legend{display:flex;gap:20px;font-size:12px;color:var(--muted);margin-top:12px}.legend i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:6px}.risk-list{display:grid;gap:11px}.risk-row{padding:12px 0;border-bottom:1px solid var(--line)}.risk-row:last-child{border-bottom:0}.risk-title{display:flex;justify-content:space-between;font-size:13px}.meter{height:7px;background:#172a32;border-radius:999px;overflow:hidden;margin:9px 0 5px}.meter span{display:block;height:100%;border-radius:999px}.risk-row small{color:var(--muted)}\r\n    .alert{display:grid;grid-template-columns:38px 1fr auto;gap:12px;align-items:start;padding:14px;border:1px solid var(--line);border-radius:13px;margin-top:10px;background:#0b1a21}.alert-icon{width:35px;height:35px;border-radius:10px;background:#302517;color:var(--amber);display:grid;place-items:center}.alert.danger .alert-icon{background:#311b20;color:var(--red)}.alert h3{margin:1px 0 5px;font-size:14px}.alert p{margin:0;color:var(--muted);font-size:12px;line-height:1.5}.alert time{font-size:11px;color:var(--muted)}\r\n    table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.07em;padding:10px;border-bottom:1px solid var(--line)}td{padding:13px 10px;border-bottom:1px solid #172932}tr:last-child td{border-bottom:0}.ticker{font-weight:750}.sub{color:var(--muted);font-size:11px;margin-top:3px}.pill{padding:4px 7px;border-radius:999px;font-size:11px;background:#162a32;color:#aac3ca}.scenario-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.scenario{padding:17px;border:1px solid var(--line);border-radius:14px;background:#0d1b22}.scenario h3{font-size:13px;margin:0 0 16px}.scenario strong{font-size:22px}.scenario p{font-size:12px;color:var(--muted);margin:8px 0 0}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.controls label{font-size:12px;color:var(--muted)}select,.text-input{background:#0b171e;color:var(--text);border:1px solid var(--line);padding:10px 11px;border-radius:9px}.stress-result{margin-top:16px;padding-top:16px;border-top:1px solid var(--line)}.stress-result strong{font-size:28px}.stress-breakdown{display:grid;gap:9px;margin-top:16px}.breakdown-row{display:grid;grid-template-columns:100px 1fr 82px;gap:12px;align-items:center;font-size:12px}.breakdown-track{height:8px;background:#182b34;border-radius:999px;overflow:hidden}.breakdown-track span{display:block;height:100%;background:var(--red)}\r\n    .ask{display:grid;grid-template-rows:auto 1fr auto;min-height:560px}.conversation{padding:12px 0;display:grid;gap:12px;align-content:start}.bubble{max-width:760px;padding:14px 16px;border-radius:14px;line-height:1.55;font-size:14px}.bubble.system{background:#0d2027;border:1px solid var(--line)}.bubble.user{background:#173930;margin-left:auto}.ask-form{display:flex;gap:8px;border-top:1px solid var(--line);padding-top:14px}.ask-form input{flex:1;background:#08161c;color:var(--text);border:1px solid var(--line);border-radius:11px;padding:13px}.method-list{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.method{min-height:160px}.method .num{color:var(--green);font-weight:800;font-size:12px}.method h3{font-size:15px;margin:12px 0 8px}.method p{color:var(--muted);font-size:13px;line-height:1.55;margin:0}.empty{padding:35px;text-align:center;color:var(--muted)}\r\n    @media(max-width:1050px){.metrics{grid-template-columns:repeat(3,1fr)}.scenario-grid{grid-template-columns:repeat(2,1fr)}.method-list{grid-template-columns:repeat(2,1fr)}}\r\n    @media(max-width:760px){.app{display:block}.sidebar{height:auto;position:static;border-right:0;border-bottom:1px solid var(--line);padding:15px}.brand{margin-bottom:12px}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap}.sidebar-note{display:none}main{padding:20px 14px 40px}.topbar{align-items:flex-start;gap:14px}.topbar h1{font-size:21px}.status{display:none}.metrics{grid-template-columns:repeat(2,1fr)}.grid-2,.grid-even{grid-template-columns:1fr}.scenario-grid,.method-list{grid-template-columns:1fr}.actions .btn:not(.primary){display:none}.card{padding:14px}.table-wrap{overflow:auto}table{min-width:680px}}\r\n  </style>\r\n<link rel=\"stylesheet\" href=\"refinement.css\" />\r\n<link rel=\"stylesheet\" href=\"institution.css\" />\r\n</head>\r\n<body><div style=\"display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 24px;background:#15231b;border-bottom:1px solid #344537;font-size:12px;flex-wrap:wrap\"><a href=\"/plans\" style=\"color:#c0ed9e;text-decoration:none\">← RiskPulse plans</a><span id=\"accountEmail\"></span><button id=\"signOut\" class=\"btn\" type=\"button\">Sign out</button></div>\r\n<a class=\"skip\" href=\"#main\">Skip to portfolio</a>\r\n<div class=\"app\">\r\n  <aside class=\"sidebar\">\r\n    <div class=\"brand\"><div class=\"mark\">R</div><div><strong>RiskPulse</strong><span>Portfolio intelligence</span></div></div>\r\n    <nav class=\"nav\" aria-label=\"Primary\">\r\n      <button class=\"mode-label mode-switch\" data-view=\"government\" aria-label=\"Open Oversight\">Oversight</button><button data-view=\"government\">Government monitor</button><button data-view=\"exchanges\">Global markets</button><button class=\"mode-label mode-switch\" data-view=\"overview\" aria-label=\"Open Executive\">Executive</button><button class=\"active\" data-view=\"overview\">Executive dashboard</button><button data-view=\"positions\">Positions</button><button data-view=\"stress\">Stress lab</button><button data-view=\"alerts\">Risk alerts</button><button data-view=\"ask\">Ask Risk</button><button class=\"mode-label mode-switch\" data-view=\"connections\" aria-label=\"Open Governance\">Governance</button><button data-view=\"connections\">Data connections</button><button data-view=\"evidence\">Decision evidence</button><button data-view=\"method\">Methodology</button>\r\n    </nav>\r\n    <div class=\"sidebar-note\"><b>Paper execution enabled</b><br>Saved portfolios and simulated trades. No real-money orders are sent.</div>\r\n  </aside>\r\n  <main id=\"main\">\r\n    <header class=\"topbar\"><div><div class=\"eyebrow\">Risk intelligence · <span id=\"sourceLabel\">No portfolio loaded</span></div><h1 id=\"pageTitle\">Portfolio overview</h1></div><div class=\"actions\"><span class=\"status\">Desktop application</span><button class=\"btn\" id=\"downloadBtn\">Export report</button><button class=\"btn primary\" id=\"importBtn\">Import positions</button><input id=\"csvFile\" type=\"file\" accept=\".csv\" aria-label=\"Import positions CSV\" /></div></header>\r\n\r\n    <div id=\"feedback\" class=\"feedback\" role=\"status\" hidden></div>\r\n    <div class=\"portfolio-bar\"><label>Portfolio equity · USD <input class=\"text-input\" id=\"equityInput\" type=\"number\" min=\"1\" step=\"any\" value=\"10000000\" /></label><button class=\"btn\" id=\"applyEquity\">Apply equity</button><p id=\"dataNote\">Import your positions and set their equity. Portfolio data remains in this tab.</p><button class=\"btn\" id=\"templateBtn\">CSV template</button><button class=\"btn\" id=\"resetBtn\">Load demonstration</button></div>\r\n    <section class=\"view active\" id=\"overview\"><div id=\"portfolioEmpty\"></div>\r\n      <div class=\"metrics\" id=\"metrics\"></div>\r\n      <div class=\"grid-2\">\r\n        <article class=\"card\"><div class=\"section-head\"><div><h2>Stress impact by scenario</h2><p>Deterministic shocks applied to current exposures</p></div><span class=\"badge\">Modeled impact</span></div><div class=\"chart\" id=\"scenarioChart\"></div><div class=\"legend\"><span><i style=\"background:var(--green)\"></i>Gain</span><span><i style=\"background:var(--red)\"></i>Loss</span></div></article>\r\n        <article class=\"card\"><div class=\"section-head\"><div><h2>Risk posture</h2><p>Limit use across four dimensions</p></div></div><div class=\"risk-list\" id=\"riskPosture\"></div></article>\r\n      </div>\r\n      <div class=\"grid-2\">\r\n        <article class=\"card\"><div class=\"section-head\"><div><h2>Risk explanation</h2><p>Current concentration and the positions responsible</p></div></div><div id=\"explanation\"></div></article>\r\n        <article class=\"card\"><div class=\"section-head\"><div><h2>Highest-priority alerts</h2><p>Threshold breaches requiring review</p></div><button class=\"btn\" data-goto=\"alerts\">View all</button></div><div id=\"alertPreview\"></div></article>\r\n      </div>\r\n    </section>\r\n\r\n    <section class=\"view\" id=\"positions\"><article class=\"card\"><div class=\"section-head\"><div><h2>Position-level risk</h2><p>Concentration, liquidity, beta, and counterparty evidence</p></div><span class=\"badge\" id=\"positionCount\"></span></div><div class=\"toolbar\"><label class=\"search\">Search positions<input class=\"text-input\" id=\"positionSearch\" type=\"search\" placeholder=\"Ticker, name or counterparty\" /></label><label>Sector<select id=\"sectorFilter\"><option value=\"all\">All sectors</option></select></label><label>Sort by<select id=\"positionSort\"><option value=\"value\">Market value</option><option value=\"ticker\">Ticker</option><option value=\"liquidity\">Days to exit</option><option value=\"pnl\">Day P&amp;L</option></select></label></div><div class=\"table-wrap\"><table><thead><tr><th>Security</th><th>Market value</th><th>Weight</th><th>Day P&amp;L</th><th>Beta</th><th>Days to exit</th><th>Counterparty / supplied credit</th><th>Risk</th></tr></thead><tbody id=\"positionRows\"></tbody></table></div></article></section>\r\n\r\n    <section class=\"view\" id=\"stress\"><div class=\"scenario-grid\" id=\"scenarioCards\"></div><div class=\"grid-even\"><article class=\"card\"><div class=\"section-head\"><div><h2>Custom shock</h2><p>Test a market or sector decline without placing a trade</p></div></div><div class=\"controls\"><label>Shock target <select id=\"shockTarget\"><option value=\"all\">Whole portfolio</option><option value=\"Technology\">Technology</option><option value=\"Financials\">Financials</option><option value=\"Energy\">Energy</option></select></label><label>Move <input class=\"text-input\" id=\"shockMove\" type=\"number\" min=\"-100\" max=\"100\" step=\"0.5\" value=\"-10\" style=\"width:105px\" aria-label=\"Shock percentage\" /> %</label><button class=\"btn primary\" id=\"runStress\">Run stress</button></div><div class=\"stress-result\"><span class=\"sub\">Estimated portfolio impact</span><br><strong class=\"down\" id=\"customLoss\">—</strong><div class=\"stress-breakdown\" id=\"stressBreakdown\"></div></div></article><article class=\"card\"><div class=\"section-head\"><div><h2>Survival check</h2><p>Loss is measured against capital, not confidence</p></div></div><div id=\"survival\"></div></article></div></section>\r\n\r\n    <section class=\"view\" id=\"alerts\"><article class=\"card\"><div class=\"section-head\"><div><h2>Risk alerts</h2><p>Reviewable evidence with transparent trigger conditions</p></div><div class=\"controls\"><label>Severity <select id=\"severityFilter\"><option value=\"all\">All</option><option value=\"danger\">Critical</option><option value=\"warning\">Warning</option></select></label></div></div><div id=\"allAlerts\"></div></article></section>\r\n\r\n    <section class=\"view\" id=\"ask\"><article class=\"card ask\"><div class=\"section-head\"><div><h2>Ask Risk</h2><p>Answers use the loaded portfolio and deterministic calculations</p></div><span class=\"badge\">Rule-based answers</span></div><div class=\"conversation\" id=\"conversation\"><div class=\"bubble system\">Ask about concentration, liquidity, counterparties, or stress scenarios. Answers use this snapshot; changes over time are not available.</div></div><div class=\"chips\"><button class=\"btn\" data-question=\"Which position is largest?\">Largest exposure</button><button class=\"btn\" data-question=\"Where is liquidity weakest?\">Liquidity</button><button class=\"btn\" data-question=\"What happens under a market shock?\">Market shock</button></div><form class=\"ask-form\" id=\"askForm\"><input id=\"askInput\" aria-label=\"Ask a risk question\" placeholder=\"Which position is largest?\" /><button class=\"btn primary\">Analyze</button></form></article></section>\r\n\r\n    <section class=\"view\" id=\"method\"><p class=\"public-note\">Public sources update through the server. Licensed stock prices require an authenticated vendor session. Directory coverage is not price-feed coverage.</p><div class=\"method-list\"><article class=\"card method\"><span class=\"num\">01</span><h3>Facts before explanations</h3><p>Price, value, exposure, volume and liquidity are measured first. Narrative is shown separately as interpretation.</p></article><article class=\"card method\"><span class=\"num\">02</span><h3>Survivable position size</h3><p>Position values are compared with portfolio equity. The single-position concentration threshold is 15%; sector concentration is 35%.</p></article><article class=\"card method\"><span class=\"num\">03</span><h3>Liquidity under stress</h3><p>Exit time equals shares divided by 10% of supplied average daily volume. Missing volume is shown as unknown. This is a normal-volume estimate, not a stressed execution forecast.</p></article><article class=\"card method\"><span class=\"num\">04</span><h3>Evidence can change the view</h3><p>Limits and alerts update when portfolio evidence changes. No conclusion is permanent merely because it was previously accepted.</p></article><article class=\"card method\"><span class=\"num\">05</span><h3>Counterparty visibility</h3><p>Exposure is aggregated by broker or custodian so a portfolio does not mistake multiple positions for diversified operational risk.</p></article><article class=\"card method\"><span class=\"num\">06</span><h3>Human responsibility</h3><p>The system observes, calculates, stresses, alerts and explains. It does not execute, hedge, move funds or claim certainty.</p></article></div><article class=\"card\" style=\"margin-top:14px\"><div class=\"section-head\"><div><h2>Calculation notes</h2><p>Transparent V1 methodology</p></div></div><p style=\"color:var(--muted);line-height:1.7;margin:0\">Market value equals shares × current price × direction. Gross exposure uses absolute values; net exposure uses signed values. Equity is a user-supplied denominator, not a calculated NAV. Day P&amp;L assumes unchanged shares and uses current value × day return / (1 + day return). Whole-portfolio shocks multiply each value by the move and supplied beta; sector shocks apply the move directly. The rates scenario is a fixed −2.5% bond-price proxy, not a duration calculation. Limits are illustrative: gross exposure 120%, position 15%, sector 35%, counterparty 25%, scenario loss 5%, and normal-volume exit time 1 day. Counterparty and sector concentration use gross absolute exposure divided by equity. Supplied credit labels are displayed without verification or a credit-loss model. Public monitoring uses dated official observations separately from portfolio inputs. No covariance model or regulatory capital calculation is provided. Non-USD positions require a supplied FX-to-USD multiplier. Prices and timestamps must be validated before institutional decisions. This model is not investment advice.</p></article></section>\r\n<section class=\"view\" id=\"government\">\r\n <div class=\"section-head\"><div><h2>Financial system monitor</h2><p>Official observations with source dates. No generated market values.</p></div><button class=\"btn primary\" id=\"refreshPublic\">Refresh sources</button></div>\r\n <div class=\"metrics public-metrics\" id=\"publicMetrics\"><article class=\"card\"><p>Connecting to official sources…</p></article></div>\r\n <div class=\"grid-2\"><article class=\"card\"><div class=\"section-head\"><div><h2>Financial stress over time</h2><p>OFR FSI · last 252 available observations</p></div><span class=\"badge\">Daily observations</span></div><div id=\"fsiChart\" class=\"time-chart\"></div><p class=\"notice\">Above zero means stress above its historical average. This is an index, not a probability of crisis.</p></article><article class=\"card\"><div class=\"section-head\"><div><h2>Evidence brief</h2><p>Deterministic observations from retrieved data</p></div></div><div id=\"systemBrief\"></div></article></div>\r\n <div class=\"grid-even\"><article class=\"card\"><div class=\"section-head\"><div><h2>Stress contributions</h2><p>Latest published OFR components</p></div></div><div id=\"fsiComponents\"></div></article><article class=\"card\"><div class=\"section-head\"><div><h2>Foreign exchange references</h2><p>ECB · units of currency per 1 EUR</p></div></div><div id=\"fxTable\"></div></article></div>\r\n <article class=\"card\" style=\"margin-top:16px\"><h2>Data provenance</h2><div class=\"table-wrap\"><table><thead><tr><th>Source</th><th>Observation date</th><th>Retrieved UTC</th><th>Status</th></tr></thead><tbody id=\"provenanceRows\"></tbody></table></div><p class=\"notice\">A recent retrieval does not make an old observation current. A warning appears after seven calendar days; source-specific publication calendars still apply.</p></article>\r\n</section>\r\n<section class=\"view\" id=\"exchanges\">\r\n <div class=\"section-head\"><div><h2>Global market directory</h2><p>Official ISO 10383 MIC register: exchanges, segments and reporting venues.</p></div><button class=\"btn\" id=\"refreshVenues\">Refresh register</button></div>\r\n <div class=\"card\"><div class=\"toolbar\"><label class=\"search\">Find a market<input class=\"text-input\" id=\"venueSearch\" placeholder=\"NYSE, Nasdaq, London, India or MIC\" /></label><label>Country<select id=\"venueCountry\"><option value=\"all\">All countries</option></select></label><label>Record type<select id=\"venueType\"><option value=\"all\">All types</option><option value=\"OPRT\">Operating MIC</option><option value=\"SGMT\">Market segment</option></select></label><label>Status<select id=\"venueStatus\"><option value=\"ACTIVE\">Active in register</option><option value=\"all\">All statuses</option></select></label></div><p id=\"venueSummary\" class=\"notice\">Loading register…</p><div class=\"table-wrap\"><table><thead><tr><th>MIC</th><th>Market / institution</th><th>Country / city</th><th>Type</th><th>Category</th><th>Registry status</th><th>Price feed</th></tr></thead><tbody id=\"venueRows\"></tbody></table></div><div class=\"controls\" style=\"margin-top:16px\"><button class=\"btn\" id=\"venuePrev\">Previous</button><span id=\"venuePage\"></span><button class=\"btn\" id=\"venueNext\">Next</button></div><p class=\"notice\">Inclusion in this register does not mean prices are connected or that a venue is a stock exchange. Monthly publications may include changes with a future implementation date. <a href=\"https://www.iso20022.org/market-identifier-codes\" target=\"_blank\" rel=\"noopener\">Registry definitions and effective dates</a></p></div>\r\n</section>\r\n<section class=\"view\" id=\"connections\">\r\n <div class=\"section-head\"><div><h2>Data connections</h2><p>Licensed access must be verified for each product and deployment.</p></div><button class=\"btn\" id=\"checkConnections\">Check connection status</button></div>\r\n <div id=\"providerStatus\" class=\"feedback\">Checking…</div>\r\n <div class=\"grid-even\"><article class=\"card\"><h2>Bloomberg Desktop API</h2><p class=\"notice\">Uses the authenticated Bloomberg Terminal on the same Windows machine. Local adapter: BLPAPI reference-data snapshots. Not a B-PIPE subscription.</p><span class=\"badge\" id=\"bloombergState\">Not connected</span></article><article class=\"card\"><h2>LSEG Workspace / Data Platform</h2><p class=\"notice\">Uses your locally configured LSEG Data Library session and licensed field entitlements. Credentials remain outside the browser.</p><span class=\"badge\" id=\"lsegState\">Not connected</span></article></div>\r\n <article class=\"card\" style=\"margin-top:16px\"><h2>Request a licensed price snapshot</h2><p class=\"notice\">Available in the local desktop edition after SDK and session setup. Enter exact vendor identifiers; no automatic symbol guessing.</p><div class=\"toolbar\"><label>Provider<select id=\"licensedProvider\"><option value=\"bloomberg\">Bloomberg Desktop</option><option value=\"lseg\">LSEG configured session</option></select></label><label class=\"search\">Instrument identifiers, separated by commas<input class=\"text-input\" id=\"licensedSymbols\" placeholder=\"AAPL US Equity or AAPL.O, depending on provider\" /></label><button class=\"btn primary\" id=\"loadLicensed\">Fetch licensed snapshot</button></div><div id=\"licensedResults\"></div></article>\r\n <article class=\"card\" style=\"margin-top:16px\"><h2>Institutional deployment status</h2><p class=\"notice\">B-PIPE server authentication, continuous streaming, exchange entitlements, government data residency, organization roles, immutable audit storage and model approval are not configured. This deployment provides decision-support calculations; it is not a certified supervisory or trading system.</p></article>\r\n</section>\r\n<section class=\"view\" id=\"evidence\">\r\n <article class=\"card\"><div class=\"section-head\"><div><h2>Decision evidence</h2><p>Export the inputs, source timestamps and assumptions used in this session.</p></div><button class=\"btn primary\" id=\"exportEvidence\">Download evidence JSON</button></div><div id=\"evidenceSummary\"></div><h3>Session activity</h3><div id=\"activityList\"></div><p class=\"notice\">Activity is kept in this tab and resets on reload. The export is a reproducible snapshot, not an immutable compliance log. Review redistribution permissions before sharing licensed data.</p></article>\r\n</section>\r\n\r\n  </main>\r\n</div>\r\n<script src=\"risk.js\"></script>\r\n<script src=\"sample.js\"></script>\r\n<script src=\"app.js\"></script>\r\n<script src=\"institution.js\"></script>\r\n<script src=\"controls.js\"></script><script src=\"workspace.js\"></script><script src=\"/account.js\"></script></body>\r\n</html>\r\n\r\n","type":"text/html; charset=utf-8"},"/index.html":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"description\" content=\"RiskPulse portfolio intelligence. Explore exposure, test scenarios, and make risk easier to understand.\"><title>RiskPulse — Understand your exposure.</title><link rel=\"stylesheet\" href=\"/landing.css\"><script src=\"/landing.js\" defer></script></head>\r\n<body>\r\n<header class=\"header wrap\"><a class=\"brand\" href=\"/\" aria-label=\"RiskPulse home\"><span class=\"brand-mark\">⌁</span>RiskPulse</a><nav aria-label=\"Main navigation\"><a href=\"#platform\">Platform</a><button class=\"text-button\" data-auth=\"signin\">Sign in</button><button class=\"button small\" data-auth=\"signup\">Create account <span>↗</span></button></nav></header>\r\n<main>\r\n<section class=\"hero wrap\" id=\"platform\"><div class=\"hero-copy\"><div class=\"eyebrow\"><span class=\"live-dot\"></span> PORTFOLIO INTELLIGENCE</div><h1>See the exposure.<br>Understand<br>the <em>risk.</em></h1><p class=\"hero-description\">Bring your portfolio into focus. Explore concentration, test market shocks, and turn complex exposure into a clearer next decision.</p><div class=\"hero-actions\"><button class=\"button\" data-auth=\"signup\">Create account <span>↗</span></button></div><div class=\"hero-note\"><span>01 /</span> Built for deliberate decisions.</div></div>\r\n<div id=\"authDialog\" class=\"account-cover\" aria-labelledby=\"authTitle\"><div class=\"auth-panel\"><a class=\"brand\" href=\"/\">RiskPulse</a><div class=\"auth-tabs\" aria-label=\"Account action\"><button type=\"button\" id=\"signupTab\" aria-pressed=\"true\">Sign up</button><button type=\"button\" id=\"signinTab\" aria-pressed=\"false\">Sign in</button></div><div class=\"eyebrow\" id=\"authEyebrow\">YOUR NEXT PERSPECTIVE</div><h2 id=\"authTitle\">Create your account.</h2><p class=\"auth-intro\" id=\"authIntro\">Start exploring your portfolio risk.</p><form id=\"authForm\"><label>Email address<input type=\"email\" name=\"email\" id=\"email\" autocomplete=\"email\" placeholder=\"you@company.com\" required maxlength=\"254\"></label><label id=\"mobileField\">Mobile number<input type=\"tel\" name=\"mobile\" id=\"mobile\" autocomplete=\"tel\" placeholder=\"+1 415 555 2671\" required maxlength=\"25\" aria-describedby=\"mobileHint\"><small id=\"mobileHint\">Include your country code. Example: +91 98765 43210.</small></label><label>Password<div class=\"password-field\"><input type=\"password\" name=\"password\" id=\"password\" autocomplete=\"new-password\" minlength=\"12\" maxlength=\"128\" placeholder=\"At least 12 characters\" required aria-describedby=\"passwordHint\"><button type=\"button\" id=\"togglePassword\" aria-label=\"Show password\">Show</button></div><small id=\"passwordHint\">Use 12–128 characters.</small></label><p id=\"formError\" class=\"form-error\" role=\"alert\"></p><button class=\"button submit-button\" id=\"submitAuth\" type=\"submit\">Create account <span>↗</span></button><p class=\"account-note\" id=\"accountNote\">Create your account, then explore Professional, Business, and Enterprise plans.</p></form><p class=\"auth-switch\" id=\"authSwitch\"></p></div></div></section>\r\n<section class=\"principles wrap\" aria-label=\"Platform capabilities\"><p>Clarity at every<br><strong>decision point.</strong></p><div><span>01</span><h2>Understand exposure</h2><p>Explore where positions, sectors, and counterparties concentrate your risk.</p></div><div><span>02</span><h2>Test what changes</h2><p>Evaluate portfolio sensitivity under defined market and sector shocks.</p></div><div><span>03</span><h2>Review with context</h2><p>Bring calculated impacts and transparent assumptions into your research.</p></div></section>\r\n\r\n<section class=\"closing wrap\"><span class=\"eyebrow\">START WITH A CLEARER VIEW</span><h2>Make risk part<br>of the conversation.</h2><button class=\"button\" data-auth=\"signup\">Create your account <span>↗</span></button></section>\r\n</main><footer class=\"wrap\"><a class=\"brand\" href=\"/\">RiskPulse</a><p>Portfolio intelligence. Human judgment.</p><span>Research and simulation · No real-money execution</span></footer>\r\n\r\n</body></html>\r\n\r\n","type":"text/html; charset=utf-8"},"/institution.css":{"body":".public-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.time-chart{min-height:230px}.time-chart svg{width:100%;height:230px;display:block}.time-chart .axis{display:flex;justify-content:space-between;color:var(--muted);font-size:13px}.data-source{font-size:13px;color:var(--muted);margin-top:8px;display:block}.feed-warning{color:var(--amber)}a{color:#89c4ff}.public-metrics .metric strong{font-size:32px}.public-metrics .metric small{min-height:20px}.mode-label{margin:18px 13px 4px;color:var(--muted);font-size:12px;letter-spacing:.08em;text-transform:uppercase}.nav{gap:4px}.sidebar{overflow-y:auto}.sidebar-note{margin-top:28px}.public-note{border-left:3px solid #6aa9ff;padding:10px 14px;margin:12px 0;background:#152639}.evidence-item{border-bottom:1px solid var(--line);padding:12px 0;font-size:14px}.evidence-item time{color:var(--muted);font-size:12px;margin-right:12px}.view h2{font-size:18px}.status-tag{padding:4px 8px;background:#1b3042;border-radius:5px;font-size:12px;white-space:nowrap}#venueRows td{vertical-align:top}#venueRows td:nth-child(2){max-width:380px}.portfolio-empty{padding:26px;border:1px dashed #476175;border-radius:12px}.portfolio-empty h2{margin-top:0}.portfolio-bar[hidden]{display:none}.model-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.model-grid label{font-size:14px;display:grid;gap:6px}.model-grid input{width:100%}.policy-box{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.policy-box label{font-size:13px;display:grid;gap:4px}.policy-box input{width:130px}\r\n@media(max-width:900px){.public-metrics{grid-template-columns:1fr}.model-grid{grid-template-columns:1fr 1fr}}@media(max-width:760px){.mode-label{display:none}.nav{padding-bottom:4px}.time-chart svg{height:200px}.model-grid{grid-template-columns:1fr}.public-metrics .metric strong{font-size:29px}}\n.nav button.mode-switch{margin:18px 0 4px;padding:7px 13px 5px;color:var(--muted);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.nav button.mode-switch:hover,.nav button.mode-switch:focus-visible{background:#17302e;color:#8df1d1}.nav button.mode-switch.active{background:#17302e;color:#8df1d1;box-shadow:inset 3px 0 var(--green)}\n\r\n[hidden]{display:none!important}\r\n\r\n#fxTable{max-height:360px;overflow:auto;padding-right:10px}\r\n\n.control-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-bottom:20px}.control-fields label{display:grid;gap:8px;font-size:14px}.control-fields input{width:100%}.sidebar{overflow-y:auto}.sidebar-note{position:static;margin-top:24px}#systemic p{line-height:1.6;font-size:16px}#systemic .notice{font-size:14px}\r\n\n#workspace p{line-height:1.55}#workspace form label{display:grid;gap:8px;font-size:14px}#workspace form h2{margin-bottom:20px}#savePortfolioForm{display:flex;flex-wrap:wrap;gap:12px;align-items:end}#workspace .public-metrics{grid-template-columns:repeat(auto-fit,minmax(150px,1fr))}\r\n","type":"text/css; charset=utf-8"},"/institution.js":{"body":"'use strict';\r\nlet publicData=null,venueData=null,venuePage=0,licensedSnapshot=null;\r\nconst activity=[],countries=new Intl.DisplayNames(['en'],{type:'region'});\r\nconst countryName=code=>{try{return countries.of(code)||code}catch{return code}};\r\nconst ageDays=date=>(Date.now()-Date.parse(date))/86400000;\r\nconst stale=feed=>feed.asOf&&ageDays(feed.asOf)>7;\r\nconst fnum=(n,d=2)=>Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});\r\nfunction logActivity(action,details){activity.unshift({at:new Date().toISOString(),action,details});if(activity.length>100)activity.pop();renderEvidence();}\r\nasync function api(path,options={}){const response=await fetch(path,{...options,signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');return data;}\r\nfunction sourceCard(title,value,feed,note){const ok=feed?.status==='available';return `<article class=\"card metric\"><label>${title}</label><strong class=\"${!ok||stale(feed)?'warn':''}\">${ok?value:'Unavailable'}</strong><small>${ok?'Observation: '+esc(feed.asOf):'Source retrieval failed'}</small><span class=\"data-source\">${esc(feed?.source||'')} · ${ok&&stale(feed)?'STALE OBSERVATION':ok?'Published data':'No replacement data'}</span><p class=\"notice\">${esc(note)}</p></article>`;}\r\nfunction chart(history,key){\r\n  if(!history?.length)return '<p class=\"notice\">No observations available.</p>';\r\n  const values=history.map(r=>r[key]),min=Math.min(0,...values),max=Math.max(0,...values),span=max-min||1;\r\n  const x=i=>30+i/(Math.max(1,values.length-1))*640,y=v=>190-(v-min)/span*160;\r\n  const points=values.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');\r\n  return `<svg viewBox=\"0 0 700 220\" role=\"img\" aria-label=\"OFR Financial Stress Index, ${esc(history[0].date)} through ${esc(history.at(-1).date)}. Latest ${values.at(-1)}.\"><line x1=\"30\" x2=\"680\" y1=\"${y(0)}\" y2=\"${y(0)}\" stroke=\"#537187\" stroke-dasharray=\"4 4\"/><text x=\"5\" y=\"${y(0)+4}\" fill=\"#a5b5c8\" font-size=\"12\">0</text><text x=\"30\" y=\"18\" fill=\"#a5b5c8\" font-size=\"12\">${fnum(max)}</text><text x=\"30\" y=\"213\" fill=\"#a5b5c8\" font-size=\"12\">${fnum(min)}</text><polyline points=\"${points}\" fill=\"none\" stroke=\"#64e3bd\" stroke-width=\"2.5\"/><circle cx=\"670\" cy=\"${y(values.at(-1))}\" r=\"4\" fill=\"#64e3bd\"/></svg><div class=\"axis\"><span>${history[0].date}</span><span>${history.at(-1).date}</span></div>`;\r\n}\r\nfunction renderPublic(){\r\n  const {fsi,sofr,fx}=publicData.feeds;\r\n  $('publicMetrics').innerHTML=sourceCard('Global financial stress',fsi.status==='available'?fnum(fsi.latest['OFR FSI']):'',fsi,'OFR FSI; positive values indicate above-average stress.')+sourceCard('Secured overnight funding',sofr.status==='available'?fnum(sofr.latest.rate)+'%':'',sofr,'SOFR; secured USD overnight funding benchmark.')+sourceCard('EUR / USD reference',fx.status==='available'?fnum(fx.rates.USD,4):'',fx,'ECB reference rate, not an executable quote.');\r\n  const brief=[];\r\n  if(fsi.status==='available'){\r\n    const latest=fsi.latest['OFR FSI'],delta=latest-fsi.previous['OFR FSI'];\r\n    brief.push(`OFR stress is ${latest>=0?'above':'below'} its historical average at ${fnum(latest)}. It ${delta>=0?'rose':'fell'} ${fnum(Math.abs(delta),3)} index points since the previous published observation.`);\r\n    $('fsiChart').innerHTML=chart(fsi.history,'OFR FSI');\r\n    const keys=['Credit','Equity valuation','Safe assets','Funding','Volatility','United States','Other advanced economies','Emerging markets'];\r\n    $('fsiComponents').innerHTML='<div class=\"allocation-key\">'+keys.map(k=>`<div><span>${k}</span><b class=\"${fsi.latest[k]>0?'warn':'up'}\">${fnum(fsi.latest[k],3)}</b></div>`).join('')+'</div><p class=\"notice\">First five rows decompose stress by category; last three decompose it by region. Do not add both decompositions together.</p>';\r\n  }else{$('fsiChart').innerHTML='<p class=\"notice\">OFR data unavailable.</p>';$('fsiComponents').textContent='No component data available.';}\r\n  if(sofr.status==='available')brief.push(`SOFR changed ${fnum((sofr.latest.rate-sofr.previous.rate)*100,1)} basis points since the previous observation. Reported transaction volume is $${fnum(sofr.latest.volumeBillions,0)} billion.`);\r\n  for(const [id,feed] of Object.entries(publicData.feeds))if(feed.status!=='available'||stale(feed))brief.push(`${feed.source}: ${feed.status!=='available'?'retrieval failed; do not infer a current value':'observation is older than seven calendar days; review publication availability'}.`);\r\n  $('systemBrief').innerHTML=brief.map(t=>'<p class=\"notice\">'+esc(t)+'</p>').join('')+'<p class=\"public-note\">These indicators support review. They do not establish causation, forecast returns, or constitute a systemic-risk certification.</p>';\r\n  $('fxTable').innerHTML=fx.status==='available'?'<div class=\"allocation-key\">'+Object.entries(fx.rates).filter(([c])=>c!=='EUR').map(([c,r])=>`<div><span>${c}</span><b>${fnum(r,4)}</b></div>`).join('')+'</div>':'<p class=\"notice\">ECB reference data unavailable.</p>';\r\n  $('provenanceRows').innerHTML=Object.values(publicData.feeds).map(feed=>`<tr><td><a href=\"${esc(feed.sourceUrl)}\" target=\"_blank\" rel=\"noopener\">${esc(feed.source)}</a></td><td>${esc(feed.asOf||'—')}</td><td>${esc(feed.fetchedAt||'—')}</td><td>${feed.status!=='available'?'Unavailable':stale(feed)?'Stale observation':'Retrieved'}${feed.cached?' · cached':''}</td></tr>`).join('');\r\n}\r\nasync function loadPublic(){const b=$('refreshPublic');b.disabled=true;b.textContent='Retrieving…';try{publicData=await api('/api/public');renderPublic();logActivity('Public sources refreshed',Object.fromEntries(Object.entries(publicData.feeds).map(([k,v])=>[k,{status:v.status,asOf:v.asOf||null}])));}catch(e){$('publicMetrics').innerHTML='<article class=\"card\"><h2>Sources unavailable</h2><p>'+esc(e.message)+'</p><p class=\"notice\">No synthetic data is substituted. Try Refresh sources.</p></article>';logActivity('Public retrieval failed',e.message);}finally{b.disabled=false;b.textContent='Refresh sources';}}\r\nfunction renderVenues(){\r\n  if(!venueData)return;const query=$('venueSearch').value.toLowerCase().trim(),country=$('venueCountry').value,type=$('venueType').value,status=$('venueStatus').value;\r\n  const rows=venueData.venues.filter(v=>(country==='all'||country===v.country)&&(type==='all'||type===v.type)&&(status==='all'||status===v.status)&&`${v.mic} ${v.name} ${v.city} ${v.country} ${countryName(v.country)}`.toLowerCase().includes(query));\r\n  const pages=Math.max(1,Math.ceil(rows.length/30));venuePage=Math.min(venuePage,pages-1);\r\n  $('venueSummary').textContent=`${rows.length.toLocaleString()} matching records · ${venueData.venues.length.toLocaleString()} total MIC records · retrieved ${venueData.fetchedAt}. Registered market identity is separate from licensed price coverage.`;\r\n  $('venueRows').innerHTML=rows.slice(venuePage*30,venuePage*30+30).map(v=>`<tr><td><b>${esc(v.mic)}</b><div class=\"sub\">Parent ${esc(v.operatingMic)}</div></td><td>${esc(v.name)}</td><td>${esc(countryName(v.country))}<div class=\"sub\">${esc(v.city)}</div></td><td>${esc(v.type)}</td><td>${esc(v.category)}</td><td>${esc(v.status)}</td><td><span class=\"status-tag\">Not verified</span></td></tr>`).join('')||'<tr><td colspan=\"7\">No matching venues.</td></tr>';\r\n  $('venuePage').textContent=`Page ${venuePage+1} of ${pages}`;$('venuePrev').disabled=venuePage===0;$('venueNext').disabled=venuePage+1>=pages;\r\n}\r\nasync function loadVenues(){const b=$('refreshVenues');b.disabled=true;try{venueData=await api('/api/venues');const cs=[...new Set(venueData.venues.map(v=>v.country))].sort((a,b)=>countryName(a).localeCompare(countryName(b)));$('venueCountry').replaceChildren(new Option('All countries','all'),...cs.map(c=>new Option(countryName(c),c)));renderVenues();logActivity('MIC register retrieved',{count:venueData.venues.length,source:venueData.source,fetchedAt:venueData.fetchedAt});}catch(e){$('venueSummary').textContent='Registry unavailable: '+e.message;}finally{b.disabled=false;}}\r\nasync function checkConnections(){try{const status=await api('/api/status');$('providerStatus').textContent=status.licensed?.reason||'Connection status received.';$('bloombergState').textContent=status.licensed?.bloombergInstalled?'SDK installed · session unverified':'SDK unavailable in this deployment';$('lsegState').textContent=status.licensed?.lsegInstalled?'SDK installed · session unverified':'SDK unavailable in this deployment';}catch{$('providerStatus').textContent='Cannot reach the data service.';}}\r\nfunction renderEvidence(){\r\n  $('evidenceSummary').innerHTML=`<p>${positions.length} portfolio positions · ${esc(source)}</p><p class=\"notice\">Public snapshot: ${esc(publicData?.generatedAt||'Not retrieved')}. Model: deterministic shocks v3; USD reporting; current positions held constant.</p>`;\r\n  $('activityList').innerHTML=activity.slice(0,20).map(a=>`<div class=\"evidence-item\"><time>${esc(a.at)}</time>${esc(a.action)}</div>`).join('')||'<p class=\"notice\">No activity recorded.</p>';\r\n}\r\n$('refreshPublic').onclick=loadPublic;$('refreshVenues').onclick=loadVenues;$('checkConnections').onclick=checkConnections;\r\nfor(const id of ['venueSearch','venueCountry','venueType','venueStatus'])$(id).addEventListener(id==='venueSearch'?'input':'change',()=>{venuePage=0;renderVenues()});\r\n$('venuePrev').onclick=()=>{venuePage--;renderVenues()};$('venueNext').onclick=()=>{venuePage++;renderVenues()};\r\n$('exportEvidence').onclick=()=>{logActivity('Decision evidence exported',{positions:positions.length});download('riskpulse-evidence.json',JSON.stringify({schemaVersion:1,generatedAt:new Date().toISOString(),source,equityUSD:equity,positions,summary:positions.length?pf():null,scenarios:positions.length?scenarios.map(s=>({...s,impactUSD:impact(s)})):[],alerts:alerts(),publicData,licensedSnapshot,activity,limitations:['User-supplied holdings and equity','No immutable server audit','No validated forecasting or regulatory capital model','Public reference data is not executable pricing']},null,2),'application/json');};\r\nfor(const id of ['applyEquity','runStress','resetBtn'])$(id).addEventListener('click',()=>logActivity(id==='applyEquity'?'Equity control used':id==='runStress'?'Stress evaluated':'Demonstration loaded',{equity,positionCount:positions.length,target:$('shockTarget').value,move:$('shockMove').value}));\r\n$('loadLicensed').onclick=async()=>{const btn=$('loadLicensed'),ids=$('licensedSymbols').value.split(',').map(x=>x.trim()).filter(Boolean);if(!ids.length||ids.length>50){$('licensedResults').textContent='Enter between 1 and 50 exact provider identifiers.';return}btn.disabled=true;try{licensedSnapshot=await api('/api/licensed/quotes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('licensedProvider').value,instruments:ids})});$('licensedResults').innerHTML='<div class=\"table-wrap\"><table><thead><tr><th>Identifier</th><th>Price</th><th>Currency</th><th>Observation</th><th>Status</th></tr></thead><tbody>'+licensedSnapshot.quotes.map(q=>`<tr><td>${esc(q.instrument)}</td><td>${q.price===null?'Unavailable':fnum(q.price,4)}</td><td>${esc(q.currency||'Unknown')}</td><td>${esc(q.asOf||'Unknown')}</td><td>${esc(q.error||q.timing)}</td></tr>`).join('')+'</tbody></table></div><p class=\"notice\">Retrieved '+esc(licensedSnapshot.retrievedAt)+'. Quotes are not automatically joined to holdings. Validate vendor identifiers, currency, units and dates before use.</p>';logActivity('Licensed snapshot retrieved',{provider:licensedSnapshot.provider,count:licensedSnapshot.quotes.length});}catch(e){$('licensedResults').textContent=e.message;logActivity('Licensed request unavailable',e.message);}finally{btn.disabled=false;}};\r\ndocument.addEventListener('portfolio-imported',e=>logActivity('Portfolio imported',{count:e.detail.count,source}));\r\nrenderEvidence();loadPublic();loadVenues();checkConnections();\r\n","type":"text/javascript; charset=utf-8"},"/landing.css":{"body":":root{--bg:#0b1411;--panel:#111e18;--line:#2b3c32;--text:#f0f1e9;--muted:#a4b4a8;--accent:#c0ed9e}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--text);font-family:Segoe UI,Arial,sans-serif;font-size:15px}button,input,select{font:inherit}button,a,input,select{-webkit-tap-highlight-color:transparent}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}button{cursor:pointer}button:disabled{cursor:wait;opacity:.65}:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.wrap{max-width:1256px;margin:auto;padding-left:40px;padding-right:40px}.header{display:flex;align-items:center;justify-content:space-between;min-height:102px;border-bottom:1px solid var(--line)}.brand{display:inline-flex;align-items:center;gap:9px;font-size:24px;font-weight:650;letter-spacing:-1px}.brand-mark{display:grid;place-items:center;width:31px;height:32px;border:1px solid var(--accent);border-radius:7px;color:var(--accent);font-size:31px}.brand-dot{font-size:10px;align-self:flex-start;letter-spacing:0;margin-top:6px}.header nav{display:flex;align-items:center;gap:29px;font-size:13px}.header nav>a{color:var(--muted)}.text-button{border:0;background:none;color:var(--text);padding:10px 0}.button{display:inline-flex;justify-content:space-between;align-items:center;gap:34px;background:var(--accent);border:1px solid var(--accent);border-radius:5px;color:#132015;font-size:14px;font-weight:650;min-height:49px;padding:13px 20px;transition:background .15s,transform .15s}.button:hover{background:#d5fac0;transform:translateY(-1px)}.button span{font-size:20px;line-height:1}.button.small{min-height:41px;padding:10px 15px;font-size:12px;gap:20px}.hero{display:grid;grid-template-columns:1fr 1fr;gap:64px;padding-top:83px;padding-bottom:68px;align-items:center}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:650;color:var(--accent);display:flex;align-items:center;gap:10px}.live-dot{display:inline-block;background:var(--accent);border-radius:50%;width:6px;height:6px}.hero h1{font-size:clamp(48px,5.6vw,76px);line-height:1.07;letter-spacing:-4px;font-weight:500;margin:27px 0 24px}.hero h1 em{font-family:Georgia,serif;font-weight:400;color:var(--accent)}.hero-description{max-width:414px;font-size:16px;line-height:1.75;color:var(--muted)}.hero-actions{display:flex;gap:28px;align-items:center;margin-top:30px}.secondary-link{font-size:13px}.secondary-link span{margin-left:15px;color:var(--accent)}.hero-note{font-size:11px;color:var(--muted);margin-top:44px}.hero-note span{color:var(--accent);margin-right:12px}.visual{position:relative;background:radial-gradient(ellipse at 80% 15%,#243826 0%,#15231b 43%,#101b16 80%);border:1px solid #3c5140;border-radius:12px;padding:25px 27px;box-shadow:0 25px 70px #0003;transform:rotate(-1deg)}.visual-top{display:flex;justify-content:space-between;gap:10px;font-size:9px;letter-spacing:1.3px;color:var(--accent);align-items:center}.visual-top i{margin-right:7px}.outline-label{border:1px solid #456046;border-radius:3px;padding:5px 6px;font-size:8px;color:#bfcebb}.visual-title{font-size:30px;line-height:1.23;font-weight:400;letter-spacing:-1px;margin:36px 0}.chart-label,.chart-footer{display:flex;justify-content:space-between;font-size:9px;color:var(--muted)}.chart-label span:last-child{color:var(--accent)}.signal-chart{width:100%;display:block;margin-top:17px}.chart-footer{font-size:8px;letter-spacing:1px}.visual-bottom{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #344537;margin-top:28px;padding-top:23px;gap:12px}.visual-bottom b{display:block;font-size:12px;font-weight:500;margin-top:11px}.visual-bottom small{display:block;font-size:9px;margin-top:6px;color:var(--muted)}.mini-icon{color:var(--accent);font-size:19px}.principles{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:30px;padding-top:32px;padding-bottom:40px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.principles>p{font-size:21px;line-height:1.4;margin:18px 0}.principles strong{font-weight:400;color:var(--accent)}.principles div>span{color:#73947c;font-size:10px}.principles h2{font-size:14px;font-weight:550}.principles div>p{color:var(--muted);font-size:12px;line-height:1.7;margin-bottom:0}.pricing{padding-top:84px;padding-bottom:64px}.pricing-heading{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:36px}.pricing-heading h2,.closing h2{font-size:44px;letter-spacing:-2px;line-height:1.1;font-weight:450;margin:18px 0 0}.pricing-heading>p{color:var(--muted);font-size:13px;line-height:1.8;margin-bottom:0}.price-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.price-card{display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:28px 24px}.price-card.featured{border-color:#8fbd73;background:linear-gradient(145deg,#243224,#142019)}.plan-number{font-size:9px;letter-spacing:1.3px;color:var(--muted);display:flex;align-items:center;justify-content:space-between;min-height:23px}.tag{font-size:8px;background:#c0ed9e;color:#15251b;padding:5px 7px;border-radius:3px}.price-card h3{font-size:24px;letter-spacing:-.5px;font-weight:500;margin:19px 0 12px}.plan-description{font-size:12px;line-height:1.8;color:var(--muted);min-height:65px;margin:0}.price{position:relative;font-size:43px;font-weight:450;letter-spacing:-1.5px;margin:24px 0 25px;white-space:nowrap}.price>span{font-size:11px;letter-spacing:0;color:var(--muted)}.price>small{position:absolute;top:-14px;left:0;font-size:10px;letter-spacing:0;color:var(--muted)}.plan-button{width:100%;font-size:12px;gap:8px;padding:11px 13px;background:transparent;color:var(--text);border-color:#465c49}.featured .plan-button{background:var(--accent);color:#132015;border-color:var(--accent)}.plan-button:hover{background:#30462c;color:var(--text)}.price-card ul{list-style:none;padding:22px 0 6px;margin:0;font-size:11px;line-height:1.65;border-top:1px solid var(--line);margin-top:23px}.price-card li{position:relative;padding-left:19px;margin-bottom:12px;color:#d1dcce}.price-card li:before{content:'✓';position:absolute;left:0;color:var(--accent)}.plan-foot{font-size:10px;line-height:1.7;color:var(--muted);margin-top:auto;padding-top:12px;margin-bottom:0}.pricing-notes{color:var(--muted);font-size:11px;line-height:1.7;text-align:center;margin-top:26px}.pricing-notes p{margin:5px 0}.closing{text-align:center;padding-top:55px;padding-bottom:72px;border-top:1px solid var(--line)}.closing .eyebrow{justify-content:center}.closing h2{margin-bottom:28px}.closing .button{margin:auto}footer{border-top:1px solid var(--line);min-height:107px;display:flex;align-items:center;justify-content:space-between;gap:25px}footer .brand{font-size:20px}footer p,footer>span{font-size:10px;color:var(--muted)}dialog{background:#122019;color:var(--text);border:1px solid #456048;border-radius:16px;padding:0;width:min(480px,calc(100vw - 28px));max-height:calc(100dvh - 36px);box-shadow:0 25px 100px #0009}dialog::backdrop{background:#030b08c9;backdrop-filter:blur(7px)}.auth-panel{padding:32px;position:relative}.close-button{position:absolute;right:19px;top:16px;border:none;background:transparent;color:var(--muted);font-size:28px}.auth-tabs{display:flex;border-bottom:1px solid var(--line);margin:26px 0}.auth-tabs button{flex:1;border:0;border-bottom:2px solid transparent;padding:12px;background:none;color:var(--muted)}.auth-tabs button[aria-pressed=true]{border-color:var(--accent);color:var(--accent)}.auth-panel h2{font-size:29px;font-weight:500;letter-spacing:-1px;margin:14px 0 8px}.auth-intro{color:var(--muted);font-size:13px;margin-bottom:24px}form label{display:block;font-size:12px;color:#dce6d8;margin-bottom:17px}form input,form select{display:block;width:100%;padding:12px 13px;background:#0b1610;color:var(--text);border:1px solid #38503e;border-radius:5px;margin-top:8px;font-size:13px;min-height:44px}form select{font-size:12px}form small{display:block;color:var(--muted);font-size:10px;line-height:1.6;margin-top:6px}.password-field{position:relative}.password-field input{padding-right:64px}.password-field button{position:absolute;right:12px;top:14px;border:0;background:none;color:var(--accent);font-size:11px}.form-error{font-size:12px;line-height:1.5;color:#ffb6a8}.form-error:empty{display:none}.submit-button{width:100%}.account-note,.auth-switch{font-size:11px;color:var(--muted);line-height:1.7}.account-note{margin:14px 0 0}.auth-switch{text-align:center;margin-bottom:0}.auth-switch button{border:0;background:none;color:var(--accent);font:inherit}.auth-panel [hidden]{display:none!important}body:has(dialog[open]){overflow:hidden}@media(min-width:1450px){.hero{padding-top:95px;padding-bottom:85px}}@media(max-width:1000px){.wrap{padding-left:25px;padding-right:25px}.hero{gap:30px}.hero h1{font-size:58px}.price-card{padding:23px 18px}.price{font-size:35px}.price>span{font-size:10px}.principles{gap:22px}}@media(max-width:760px){.header{min-height:82px}.header nav{gap:18px}.header nav>a{display:none}.brand{font-size:21px}.brand-mark{width:25px;height:27px}.hero{grid-template-columns:1fr;padding-top:47px;padding-bottom:45px;gap:40px}.hero h1{font-size:61px;letter-spacing:-3px}.hero-description{font-size:15px}.hero-note{margin-top:27px}.visual{transform:none;max-width:520px;width:100%;margin:auto}.principles{grid-template-columns:1fr 1fr;padding-top:28px;gap:25px}.principles>p{font-size:23px;margin:10px 0}.pricing{padding-top:54px}.pricing-heading{display:block}.pricing-heading>p{margin-top:22px}.pricing-heading h2,.closing h2{font-size:39px}.price-grid{grid-template-columns:1fr}.price-card{padding:28px}.plan-description{min-height:0;max-width:360px}.price{font-size:43px;margin-top:30px}.price>span{font-size:13px}.plan-button{font-size:14px}.price-card ul{font-size:13px}.plan-foot{font-size:11px}footer{flex-wrap:wrap;justify-content:center;text-align:center;padding-top:26px;padding-bottom:26px;gap:12px}footer>span{width:100%}footer p{margin:0}.closing{padding-top:42px;padding-bottom:45px}.auth-panel{padding:27px 23px}}@media(max-width:390px){.wrap{padding-left:18px;padding-right:18px}.header nav{gap:12px}.header .button.small{padding:9px;font-size:10px;gap:7px}.hero h1{font-size:52px}.hero-actions{gap:20px}.visual{padding:22px 18px}.visual-top{font-size:8px}.outline-label{font-size:7px}.price-card{padding:24px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}\r\n\r\n.account-cover{background:var(--panel);border:1px solid #456048;border-radius:16px;width:100%;max-width:520px;justify-self:center}.account-cover .auth-tabs{margin-top:18px}.hero{align-items:start}.account-cover .auth-panel{padding:28px}.account-cover form label{margin-bottom:13px}\r\n","type":"text/css; charset=utf-8"},"/landing.js":{"body":"const dialog=document.getElementById('authDialog'),form=document.getElementById('authForm');\r\nlet mode='signup',busy=false,localIdentity=null;\r\nconst ownerSignin=()=>localIdentity?.localOwner&&document.getElementById('email').value.trim().toLowerCase()===localIdentity.email;\r\nfunction updatePassword(){const email=document.getElementById('email');email.value=email.value.replace(/\\\\@/g,'@');const password=document.getElementById('password');const skip=Boolean(ownerSignin());password.required=!skip;password.disabled=skip;password.closest('label').hidden=skip;const mobile=document.getElementById('mobile');mobile.required=mode==='signup'&&!skip;mobile.disabled=mode!=='signup'||skip;document.getElementById('mobileField').hidden=mobile.disabled;if(!busy)document.getElementById('submitAuth').textContent=skip||mode==='signin'?'Sign in ↗':'Create account ↗';}\r\ndocument.getElementById('email').addEventListener('input',updatePassword);\r\ndocument.getElementById('email').addEventListener('change',updatePassword);\r\nfunction setMode(next){\r\n if(busy)return;\r\n mode=next;const signup=mode==='signup';\r\n document.getElementById('authTitle').textContent=signup?'Create your account.':'Welcome back.';\r\n document.getElementById('authIntro').textContent=signup?'Start exploring your portfolio risk.':'Sign in to open your RiskPulse dashboard.';\r\n document.getElementById('signupTab').setAttribute('aria-pressed',String(signup));\r\n document.getElementById('signinTab').setAttribute('aria-pressed',String(!signup));\r\n document.getElementById('mobileField').hidden=!signup;document.getElementById('mobile').required=signup;document.getElementById('mobile').disabled=!signup;\r\n const password=document.getElementById('password');password.minLength=signup?12:1;password.autocomplete=signup?'new-password':'current-password';password.placeholder=signup?'At least 12 characters':'Your password';password.value='';password.type='password';\r\n document.getElementById('togglePassword').textContent='Show';document.getElementById('togglePassword').setAttribute('aria-label','Show password');\r\n document.getElementById('passwordHint').hidden=!signup;document.getElementById('accountNote').hidden=!signup;\r\n document.getElementById('submitAuth').textContent=signup?'Create account ↗':'Sign in ↗';document.getElementById('formError').textContent='';\r\n const switcher=document.getElementById('authSwitch');switcher.replaceChildren(document.createTextNode(signup?'Already have an account? ':'New to RiskPulse? '));\r\n const button=document.createElement('button');button.type='button';button.textContent=signup?'Sign in':'Create account';button.onclick=()=>setMode(signup?'signin':'signup');switcher.append(button);updatePassword();\r\n}\r\nfunction openAuth(next,plan){if(busy)return;setMode(next);dialog.scrollIntoView({behavior:'smooth',block:'center'});document.getElementById('email').focus();}\r\ndocument.querySelectorAll('[data-auth]').forEach(button=>button.addEventListener('click',()=>openAuth(button.dataset.auth,button.dataset.plan)));\r\ndocument.getElementById('signupTab').onclick=()=>{if(!busy)setMode('signup');};document.getElementById('signinTab').onclick=()=>{if(!busy)setMode('signin');};\r\ndocument.getElementById('togglePassword').onclick=event=>{const input=document.getElementById('password'),show=input.type==='password';input.type=show?'text':'password';event.target.textContent=show?'Hide':'Show';event.target.setAttribute('aria-label',show?'Hide password':'Show password');};\r\nform.addEventListener('submit',async event=>{\r\n event.preventDefault();if(busy)return;\r\n if(ownerSignin()){location.assign('/app');return;}\r\n const data=Object.fromEntries(new FormData(form));\r\n if(mode==='signup'&&!/^\\+[1-9]\\d{7,14}$/.test(data.mobile.replace(/[\\s()-]/g,''))){document.getElementById('formError').textContent='Enter a mobile number with country code, such as +14155552671.';return;}\r\n busy=true;const controls=[...dialog.querySelectorAll('button')];controls.forEach(button=>button.disabled=true);document.getElementById('submitAuth').textContent=mode==='signup'?'Creating account…':'Signing in…';document.getElementById('formError').textContent='';\r\n try{const response=await fetch('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to continue. Please try again.');location.assign('/plans');}\r\n catch(error){document.getElementById('formError').textContent=error.message==='Failed to fetch'?'Unable to reach RiskPulse. Check that the local application is running.':error.message;}\r\n finally{busy=false;controls.forEach(button=>button.disabled=false);document.getElementById('mobile').disabled=mode!=='signup';document.getElementById('submitAuth').textContent=mode==='signup'?'Create account ↗':'Sign in ↗';}\r\n});\r\nsetMode('signup');\r\nif(new URLSearchParams(location.search).get('auth')==='signin')openAuth('signin');\r\nfetch('/api/auth/me').then(r=>r.json()).then(({user})=>{localIdentity=user;updatePassword();if(user){const button=document.querySelector('.header [data-auth=\"signin\"]');const link=document.createElement('a');link.href='/app';link.textContent='Open dashboard ↗';button.replaceWith(link);}}).catch(()=>{});","type":"text/javascript; charset=utf-8"},"/plans.html":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>RiskPulse — Choose your plan</title><link rel=\"stylesheet\" href=\"/landing.css\"><script src=\"/plans.js\" defer></script></head><body><header class=\"header wrap\"><a class=\"brand\" href=\"/\">RiskPulse</a><nav><a href=\"/app\">Open dashboard ↗</a></nav></header><main><section class=\"pricing wrap\" id=\"pricing\"><div class=\"pricing-heading\"><div><div class=\"eyebrow\">PLANS & PRICING</div><h2>Your perspective.<br>Your scale.</h2></div><p>From independent research to organizational needs.<br>All prices in US dollars.</p></div><div class=\"price-grid\">\r\n<article class=\"price-card\"><div class=\"plan-number\">01 / INDEPENDENT</div><h3>Professional</h3><p class=\"plan-description\">For professionals evaluating portfolio exposure and testing trading scenarios.</p><div class=\"price\">$199 <span>/ user / month</span></div><button class=\"button plan-button\" data-plan=\"professional\">Choose Professional <span>↗</span></button><ul><li>Portfolio exposure analysis</li><li>Market and sector scenarios</li><li>Calculated risk summaries</li></ul><p class=\"plan-foot\">One named user.</p></article>\r\n<article class=\"price-card featured\"><div class=\"plan-number\">02 / SMALL TEAMS <span class=\"tag\">BUSINESS</span></div><h3>Business</h3><p class=\"plan-description\">For small teams. Includes up to 3 users.</p><div class=\"price\">$499 <span>/ month</span></div><button class=\"button plan-button\" data-plan=\"business\">Choose Business <span>↗</span></button><ul><li>Up to 3 users in the agreed package</li><li>Team capabilities defined by agreement</li><li>Support defined in your package</li></ul><p class=\"plan-foot\">Team capabilities and support are defined in the agreed package.</p></article>\r\n<article class=\"price-card\"><div class=\"plan-number\">03 / ORGANIZATIONS</div><h3>Enterprise</h3><p class=\"plan-description\">For organizations requiring tailored deployment, integrations, and support.</p><div class=\"price enterprise-price\"><small>Starting at</small>$3,000 <span>/ month</span></div><button class=\"button plan-button\" data-plan=\"enterprise\">Register enterprise interest <span>↗</span></button><ul><li>Tailored deployment requirements</li><li>Integration scope by agreement</li><li>Defined support commitments</li></ul><p class=\"plan-foot\">Annual agreement. Scope and implementation priced by requirements.</p></article>\r\n</div><div class=\"pricing-notes\"><p>Third-party market-data subscriptions and custom implementation are separate.</p><p>Selecting a plan saves your preference. No payment is collected and no subscription is activated yet.</p></div></section><p class=\"wrap\" id=\"planStatus\" role=\"status\"></p><section class=\"closing wrap\" aria-labelledby=\"supportTitle\"><div class=\"eyebrow\">CUSTOMER SUPPORT</div><h2 id=\"supportTitle\">Questions? We can help.</h2><p>For customer enquiries, subscription questions, and support, email us.</p><a class=\"button\" href=\"mailto:bjtmusic12@gmail.com\">bjtmusic12@gmail.com <span>↗</span></a></section></main></body></html>","type":"text/html; charset=utf-8"},"/plans.js":{"body":"const status=document.getElementById('planStatus');\ndocument.querySelectorAll('[data-plan]').forEach(button=>button.addEventListener('click',async()=>{\n const buttons=[...document.querySelectorAll('[data-plan]')];buttons.forEach(b=>b.disabled=true);\n try{const response=await fetch('/api/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan:button.dataset.plan})});const result=await response.json();if(response.status===401){location.assign('/?auth=signin');return;}if(!response.ok)throw new Error(result.error||'Unable to save plan.');status.replaceChildren(document.createTextNode(button.dataset.plan[0].toUpperCase()+button.dataset.plan.slice(1)+' preference saved. No subscription has been activated. '));const link=document.createElement('a');link.href='/app';link.className='button';link.textContent='Continue to dashboard ↗';status.append(link);status.scrollIntoView({behavior:'smooth',block:'center'});}catch(error){status.textContent=error.message;}finally{buttons.forEach(b=>b.disabled=false);}\n}));\r\n","type":"text/javascript; charset=utf-8"},"/refinement.css":{"body":":root{--bg:#080f19;--panel:#101b2a;--panel2:#172437;--line:#29394b;--muted:#a5b5c8;--green:#64e3bd;--radius:14px}\nbody{background:radial-gradient(ellipse at 85% 0,#18304780,transparent 52%),var(--bg);line-height:1.5}\n.app{grid-template-columns:218px minmax(0,1fr)}.sidebar{background:#09121e;padding:28px 16px}.brand{margin-bottom:40px}.mark{background:#64e3bd;color:#09251e;border:0;box-shadow:0 0 28px #64e3bd18}.brand span{font-size:12px}.nav{gap:8px}.nav button{font-size:14px;padding:13px 15px}.nav button.active{background:#17302e;color:#8df1d1}.sidebar-note{font-size:13px;position:static;margin-top:48px}\nmain{padding:32px 32px 56px;min-width:0}.topbar{gap:20px;margin-bottom:20px;flex-wrap:wrap}.topbar h1{font-size:30px;font-weight:650;letter-spacing:-.04em}.eyebrow{font-size:12px}.actions{flex-wrap:wrap}.btn{font-size:14px;padding:10px 15px;min-height:42px}.status{font-size:13px}.card{background:linear-gradient(130deg,#132132,#0f1a28);padding:20px}.metrics{gap:12px}.metric label{font-size:14px}.metric strong{font-size:27px;font-variant-numeric:tabular-nums}.metric small{font-size:13px}.section-head h2{font-size:17px}.section-head p{font-size:14px}.badge,.pill{font-size:12px}.risk-title{font-size:14px}.risk-row small{font-size:13px}.alert p{font-size:14px}.alert time{font-size:12px}.alert{background:#0d1927;grid-template-columns:32px 1fr}.alert time{display:none}.alert-icon{width:30px;height:30px}.sub{font-size:13px}.method p{font-size:14px}.scenario h3{font-size:14px}.scenario p{font-size:14px}.controls label{font-size:14px}table{font-size:14px}th{font-size:12px}.ticker{color:#edf6ff}.table-wrap{overflow:auto}.chart{height:auto;display:grid;gap:18px;border:0;padding:8px 0}.impact-label{display:flex;justify-content:space-between;gap:16px;font-size:14px;margin-bottom:8px}.impact-track{height:11px;background:#1c2c40;border-radius:4px;overflow:hidden}.impact-track span{display:block;height:100%;background:#ff8b88;border-radius:4px}.impact-track span.gain{background:var(--green)}.legend{font-size:13px}.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:0 0 20px}.toolbar label{display:grid;gap:5px;font-size:13px;color:var(--muted)}.toolbar input{width:190px}.toolbar .search{flex:1}.toolbar .search input{width:100%;min-width:180px}.portfolio-bar{display:flex;flex-wrap:wrap;gap:16px;align-items:end;background:#0e1b29;border:1px solid var(--line);border-radius:12px;padding:14px 18px;margin-bottom:20px}.portfolio-bar label{font-size:13px;color:var(--muted)}.portfolio-bar input{width:155px;margin-left:8px}.portfolio-bar p{font-size:13px;color:var(--muted);margin:0;flex:1;min-width:180px}.feedback{padding:12px 16px;border:1px solid #42645d;border-radius:9px;background:#102c27;margin-bottom:16px;font-size:14px}.feedback.error{background:#341f29;border-color:#99545e}.feedback[hidden]{display:none}.breakdown-row{grid-template-columns:70px 1fr 110px;font-size:14px}.ask-form{flex-wrap:wrap}.ask-form input{min-width:160px}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid var(--green);outline-offset:3px}.skip{position:absolute;left:20px;top:-70px;background:var(--green);color:#071b14;padding:12px;z-index:10}.skip:focus{top:10px}.method-list{grid-template-columns:repeat(2,1fr)}.allocation{display:flex;gap:4px;height:10px;margin:18px 0;border-radius:4px;overflow:hidden}.allocation span{min-width:2px}.allocation-key{display:grid;gap:8px}.allocation-key div{display:flex;justify-content:space-between;gap:12px;font-size:14px}.allocation-key i{width:9px;height:9px;display:inline-block;border-radius:2px;margin-right:8px}.notice{color:var(--muted);font-size:13px}.positive{color:var(--green)}\n@media(max-width:1200px){.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.grid-2{grid-template-columns:1fr 1fr}main{padding:24px}.topbar h1{font-size:27px}}\n@media(max-width:900px){.app{grid-template-columns:180px minmax(0,1fr)}main{padding:20px}.grid-2,.grid-even{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.metric strong{font-size:24px}.method-list{grid-template-columns:1fr}}\n@media(max-width:760px){.app{display:block}.sidebar{padding:16px}.brand{margin-bottom:14px}.nav{gap:4px}.nav button{padding:10px 12px}.sidebar-note{display:none}main{padding:20px 14px}.topbar{display:block}.actions{margin-top:16px}.actions .btn:not(.primary){display:inline-block}.metrics{gap:8px}.metric{padding:14px}.metric strong{font-size:23px}.section-head{flex-wrap:wrap;gap:12px}.portfolio-bar{padding:14px;align-items:start}.portfolio-bar label{display:grid;gap:5px}.portfolio-bar input{margin:0;width:100%}.portfolio-bar p{flex-basis:100%}.chart{gap:20px}.scenario-grid{grid-template-columns:1fr 1fr}.scenario{padding:14px}.scenario strong{font-size:20px}.breakdown-row{grid-template-columns:54px 1fr 102px;gap:8px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n","type":"text/css; charset=utf-8"},"/risk.js":{"body":"/* Pure calculations: current marked values, USD equity, deterministic shocks. */\r\n(function(root){\r\n  const value=p=>p.shares*p.price*p.side;\r\n  const exitDays=p=>p.adv>0?p.shares/(p.adv*.1):null;\r\n  function totals(positions,key,gross=true){return positions.reduce((a,p)=>{a[p[key]]=(a[p[key]]||0)+(gross?Math.abs(value(p)):value(p));return a},Object.create(null));}\r\n  function summary(positions,equity){\r\n    const gross=positions.reduce((s,p)=>s+Math.abs(value(p)),0),net=positions.reduce((s,p)=>s+value(p),0);\r\n    const day=positions.reduce((s,p)=>s+value(p)*p.day/(100+p.day),0);\r\n    return {gross:gross/equity*100,net:net/equity*100,day,largest:Math.max(0,...positions.map(p=>Math.abs(value(p))))/equity*100};\r\n  }\r\n  function stress(positions,target,move){return positions.map(p=>({p,x:(target==='all'||p.sector===target)?value(p)*move*(target==='all'?p.beta:1):0}));}\r\n  function parseCSV(text){\r\n    text=text.replace(/^\\uFEFF/,'');let rows=[],row=[],field='',quoted=false,closed=false;\r\n    for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='\"'){if(text[i+1]==='\"'){field+='\"';i++}else{quoted=false;closed=true}}else field+=c;continue;}\r\n      if(c==='\"'){if(field.trim()||closed)throw Error('Invalid quote in CSV.');quoted=true;}\r\n      else if(c===','){row.push(field.trim());field='';closed=false;}\r\n      else if(c==='\\n'||c==='\\r'){if(c==='\\r'&&text[i+1]==='\\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field='';closed=false;}\r\n      else{if(closed&&!/\\s/.test(c))throw Error('Unexpected text after a quoted field.');field+=c;}\r\n    }\r\n    if(quoted)throw Error('Unclosed quoted field.');row.push(field.trim());if(row.some(Boolean))rows.push(row);\r\n    if(rows.length<2)throw Error('Include a header and at least one position.');\r\n    if(rows.length>5001)throw Error('Import up to 5,000 positions at a time.');\r\n    const heads=rows.shift().map(x=>x.toLowerCase());if(new Set(heads).size!==heads.length)throw Error('Duplicate column names.');\r\n    for(const h of ['ticker','shares','price','sector'])if(!heads.includes(h))throw Error('Missing required column: '+h);\r\n    return rows.map((cells,i)=>{\r\n      if(cells.length!==heads.length)throw Error('Row '+(i+2)+': column count does not match the header.');\r\n      const o=Object.fromEntries(heads.map((h,j)=>[h,cells[j]]));\r\n      const fail=m=>{throw Error('Row '+(i+2)+': '+m)};\r\n      const num=(key,fallback,min,strict=false)=>{if(!o[key]&&fallback!==undefined)return fallback;const n=Number(o[key]);if(!o[key]||!Number.isFinite(n)||(strict?n<=min:n<min))fail('invalid '+key);return n};\r\n      if(!o.ticker||!o.sector)fail('ticker and sector cannot be empty');\r\n      const side=(o.side||'long').toLowerCase();if(!['long','short'].includes(side))fail('side must be long or short');\r\n      const currency=(o.currency||'USD').toUpperCase();if(!/^[A-Z]{3}$/.test(currency))fail('currency must be a three-letter ISO code');\r\n      const fx=currency==='USD'?1:num('fx_to_usd',undefined,0,true);\r\n      const nativePrice=num('price',undefined,0,true);\r\n      if(o.asof&&(!/^\\d{4}-\\d{2}-\\d{2}$/.test(o.asof)||!Number.isFinite(Date.parse(o.asof))||Date.parse(o.asof)>Date.now()+86400000))fail('invalid asof date');\r\n      return {currency,fxToUSD:fx,nativePrice,asOf:o.asof||null,instrumentId:o.instrument_id||null,mic:o.mic||null,priceSource:o.source||'User import',ticker:o.ticker,name:o.name||o.ticker,sector:o.sector,shares:num('shares',undefined,0,true),price:nativePrice*fx,day:num('day',0,-100,true),beta:num('beta',1,-100),adv:num('adv',null,0,true),cp:o.counterparty||'Unspecified',credit:o.credit||'N/A',side:side==='short'?-1:1};\r\n    });\r\n  }\r\n  const api={value,exitDays,totals,summary,stress,parseCSV};if(typeof module!=='undefined')module.exports=api;else root.Risk=api;\r\n})(typeof globalThis!=='undefined'?globalThis:this);\r\n","type":"text/javascript; charset=utf-8"},"/sample.js":{"body":"const samplePositions=[\r\n {ticker:'NVDA',name:'NVIDIA',sector:'Technology',shares:12000,price:178.2,day:-2.6,beta:1.66,adv:188000000,cp:'Interactive Brokers',credit:'A',side:1},\r\n {ticker:'MSFT',name:'Microsoft',sector:'Technology',shares:4200,price:514.4,day:-1.1,beta:1.02,adv:21000000,cp:'Schwab',credit:'AA+',side:1},\r\n {ticker:'AMD',name:'Advanced Micro Devices',sector:'Technology',shares:8500,price:162.1,day:-3.8,beta:1.78,adv:52000000,cp:'Interactive Brokers',credit:'BBB+',side:1},\r\n {ticker:'JPM',name:'JPMorgan Chase',sector:'Financials',shares:6200,price:294.7,day:.8,beta:1.08,adv:8900000,cp:'Prime Broker A',credit:'A-',side:1},\r\n {ticker:'XOM',name:'Exxon Mobil',sector:'Energy',shares:10000,price:117.3,day:1.4,beta:.82,adv:16500000,cp:'Schwab',credit:'AA-',side:1},\r\n {ticker:'TSLA',name:'Tesla short',sector:'Consumer',shares:3500,price:426.6,day:-2.2,beta:2.08,adv:75000000,cp:'Prime Broker A',credit:'BBB',side:-1},\r\n {ticker:'BND',name:'Vanguard Total Bond',sector:'Fixed Income',shares:24000,price:74.1,day:.1,beta:.12,adv:7600000,cp:'Custodian B',credit:'AA',side:1}\r\n];\r\n","type":"text/javascript; charset=utf-8"},"/workspace.js":{"body":"'use strict';\n(() => {\nlet state={accounts:[],portfolios:[]},activeId='',pendingKey=null,busy=false;\nconst usd=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(c/100),account=()=>state.accounts.find(a=>a.id===activeId);\nconst panel=document.createElement('section');panel.id='workspace';panel.className='view';\npanel.innerHTML=`<div class=\"section-head\"><div><h2>Portfolio management & paper trading</h2><p>Build a portfolio, simulate execution, and review the resulting risk.</p></div><button class=\"btn\" id=\"workspaceRefresh\">Refresh saved data</button></div><p class=\"public-note\">Desktop workspace · saved on this computer. Paper orders use your assumed USD fill price; they do not reach a broker. Marks remain at the last assumed fill until another trade. No live execution, dividends, tax lots, leverage or short sales.</p><p id=\"workspaceMessage\" class=\"feedback\" role=\"status\">Opening saved workspace…</p><div id=\"workspaceBody\" hidden><div class=\"grid-even\"><form class=\"card\" id=\"accountForm\"><h2>Create a paper account</h2><div class=\"control-fields\"><label>Account name<input class=\"text-input\" name=\"accountName\" maxlength=\"100\" required placeholder=\"Strategy practice\"></label><label>Starting cash (USD)<input class=\"text-input\" name=\"cash\" type=\"number\" min=\"0.01\" max=\"10000000000\" step=\"0.01\" required value=\"100000\"></label><label>Maximum order (% of marked equity)<input class=\"text-input\" name=\"limitPct\" type=\"number\" min=\"1\" max=\"100\" step=\"1\" required value=\"10\"></label></div><button class=\"btn primary\">Create paper account</button></form><article class=\"card\"><h2>Saved portfolios</h2><p>Import positions using the top button, then save the current analysis portfolio here.</p><form id=\"savePortfolioForm\"><label>Snapshot name<input class=\"text-input\" name=\"snapshotName\" maxlength=\"100\" placeholder=\"September review\" required></label><button class=\"btn\">Save current portfolio</button></form><div id=\"savedPortfolios\"></div></article></div><article class=\"card\" style=\"margin-top:16px\"><div class=\"toolbar\"><label>Paper account<select id=\"paperAccount\"><option value=\"\">Create an account to begin</option></select></label><button class=\"btn\" id=\"loadPaperRisk\">Load holdings into risk dashboard</button><button class=\"btn\" id=\"paperExport\">Export account & ledger</button></div><div id=\"paperSummary\"></div></article><form class=\"card\" id=\"paperOrderForm\" style=\"margin-top:16px\"><h2>Execute a paper order</h2><div class=\"control-fields\"><label>Side<select name=\"side\"><option value=\"buy\">Buy</option><option value=\"sell\">Sell</option></select></label><label>Ticker<input class=\"text-input\" name=\"ticker\" pattern=\"[A-Za-z0-9][A-Za-z0-9.\\-]{0,19}\" maxlength=\"20\" required placeholder=\"AAPL\"></label><label>Sector<input class=\"text-input\" name=\"sector\" required maxlength=\"100\" value=\"Technology\"></label><label>Whole shares<input class=\"text-input\" name=\"quantity\" type=\"number\" min=\"1\" max=\"100000000\" step=\"1\" required></label><label>Assumed fill price (USD)<input class=\"text-input\" name=\"price\" type=\"number\" min=\"0.01\" max=\"10000000000\" step=\"0.01\" required></label><label>Fee (USD)<input class=\"text-input\" name=\"fee\" type=\"number\" min=\"0\" max=\"10000000000\" step=\"0.01\" value=\"0\" required></label></div><button class=\"btn primary\" id=\"paperExecute\">Execute paper order</button><p class=\"notice\">Immediate simulated fill at the entered price. No claim of market availability or guaranteed execution. A rejected order leaves cash and holdings unchanged.</p></form><div class=\"grid-even\"><article class=\"card\"><h2>Paper holdings</h2><div id=\"paperHoldings\" class=\"table-wrap\"></div></article><article class=\"card\"><h2>Execution ledger</h2><div id=\"paperLedger\" class=\"table-wrap\"></div></article></div></div>`;\ndocument.querySelector('main').append(panel);\nconst guardFields=[['depth','Available displayed depth (USD)',100000],['duplicate','Duplicate depth assumption (%)',20],['withdrawal','Additional depth withdrawal (%)',20],['quoteAge','Assumed quote age (ms)',20],['maxAge','Maximum quote age (ms)',100],['cancelRate','Assumed cancellation rate (%)',20],['maxCancelRate','Maximum cancellation rate (%)',80],['inventoryLimit','Maximum account inventory (USD)',100000],['shockPct','Correlated downward price shock (%)',10],['lossBudget','Maximum scenario loss (USD)',10000]];\nconst guardForm=document.createElement('form');guardForm.id='paperGuardForm';guardForm.className='card';guardForm.style.marginTop='16px';guardForm.innerHTML=`<h2>Execution risk gates</h2><p>Apply the cancellation, liquidity, inventory and cross-asset scenarios to this account. These are manually entered assumptions, not live HFT detection.</p><div class=\"controls\"><label><input type=\"checkbox\" name=\"enabled\"> Enable scenario gates</label><label><input type=\"checkbox\" name=\"paused\"> Pause all paper execution</label></div><div class=\"control-fields\">${guardFields.map(([k,label,v])=>`<label>${label}<input class=\"text-input\" name=\"${k}\" type=\"number\" min=\"${k==='maxAge'?1:0}\" max=\"${['duplicate','withdrawal','cancelRate','maxCancelRate','shockPct'].includes(k)?100:10000000000}\" step=\"any\" value=\"${v}\" required></label>`).join('')}</div><button class=\"btn\" id=\"saveGuard\">Save execution controls</button><p class=\"notice\">Depth = displayed × (1 − duplicates) × (1 − withdrawals). New buys also check post-order gross inventory and a uniform loss scenario: exposure × shock %. Sells still check pause, quote age, cancellation rate and depth. Settings remain in effect until changed; they do not refresh from a feed.</p>`;\n$('paperOrderForm').before(guardForm);\nconst nav=document.createElement('button');nav.dataset.view='workspace';nav.textContent='Portfolio workspace';nav.onclick=()=>show('workspace');document.querySelector('.nav').prepend(nav);\nconst message=(s,error=false)=>{const el=$('workspaceMessage');el.textContent=s;el.classList.toggle('error',error);};\nasync function request(data){return api('/api/workspace',data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});}\nfunction renderWorkspace(){\n const picker=$('paperAccount');picker.replaceChildren(...(state.accounts.length?state.accounts.map(a=>new Option(a.name,a.id)):[new Option('Create an account to begin','')]));\n if(!state.accounts.some(a=>a.id===activeId))activeId=state.accounts[0]?.id||'';picker.value=activeId;\n const a=account();$('paperExecute').disabled=!a;$('paperExport').disabled=!a;$('loadPaperRisk').disabled=!a||!Object.keys(a.holdings).length;\n $('saveGuard').disabled=!a;\n if(a){for(const [k,,v] of guardFields)guardForm.elements[k].value=a.guard?.[k]??v;guardForm.elements.enabled.checked=!!a.guard?.enabled;guardForm.elements.paused.checked=!!a.guard?.paused;}\n $('savedPortfolios').replaceChildren();for(const p of state.portfolios){const row=document.createElement('p'),b=document.createElement('button');b.className='btn';b.textContent='Load '+p.name;b.onclick=()=>{positions=structuredClone(p.positions);equity=p.equity;source=p.source+' · saved '+p.savedAt;$('equityInput').value=equity;render();renderEvidence();show('overview');feedback('Saved portfolio loaded. New edits require another save.');};row.append(b,document.createTextNode(' '+p.positions.length+' positions · '+p.savedAt.slice(0,10)));$('savedPortfolios').append(row);}\n if(!state.portfolios.length)$('savedPortfolios').textContent='No saved portfolios yet.';\n if(!a){$('paperSummary').textContent='Create a paper account with your chosen starting cash.';$('paperHoldings').textContent='No account selected.';$('paperLedger').textContent='No account selected.';return;}\n const holdings=Object.entries(a.holdings),marked=holdings.reduce((s,[,h])=>s+h.quantity*h.mark,0),cost=holdings.reduce((s,[,h])=>s+h.cost,0);\n $('paperSummary').innerHTML=`<div class=\"metrics public-metrics\">${[['Cash',usd(a.cash)],['Marked equity',usd(a.cash+marked)],['Realized P&L',usd(a.realized)],['Unrealized P&L',usd(marked-cost)]].map(([k,v])=>`<article class=\"metric\"><label>${k}</label><strong>${v}</strong></article>`).join('')}</div><p>Maximum order: ${a.limitPct}% of marked equity · Fees paid: ${usd(a.fees)} · ${a.trades.length} recorded fills.</p><p class=\"${a.guard?.paused?'warn':''}\">Execution: ${a.guard?.paused?'PAUSED':a.guard?.enabled?'Scenario gates enabled':'Cash, holdings and order-size checks only'}</p>`;\n $('paperHoldings').innerHTML=holdings.length?'<table><thead><tr><th>Ticker</th><th>Shares</th><th>Assumed mark</th><th>Value</th></tr></thead><tbody>'+holdings.map(([t,h])=>`<tr><td>${esc(t)}</td><td>${h.quantity}</td><td>${usd(h.mark)}</td><td>${usd(h.mark*h.quantity)}</td></tr>`).join('')+'</tbody></table>':'No holdings. Execute a paper buy to begin.';\n $('paperLedger').innerHTML=a.trades.length?'<table><thead><tr><th>Time UTC</th><th>Order</th><th>Price</th><th>Fee</th></tr></thead><tbody>'+[...a.trades].reverse().slice(0,100).map(t=>`<tr><td>${esc(t.at.slice(0,19))}</td><td>${esc(t.side)} ${t.quantity} ${esc(t.ticker)}</td><td>${usd(t.price)}</td><td>${usd(t.fee)}</td></tr>`).join('')+'</tbody></table><p class=\"notice\">Latest 100 fills. Export includes the complete ledger.</p>':'No paper orders recorded.';\n}\nasync function refresh(){try{state=await request();$('workspaceBody').hidden=false;renderWorkspace();message('Saved workspace ready. Changes are stored on this computer.');}catch(e){$('workspaceBody').hidden=true;message(e.message,true);}}\nasync function mutation(form,data){if(busy)return false;busy=true;const controls=[...panel.querySelectorAll('button,input,select')].map(el=>[el,el.disabled]);for(const [el] of controls)el.disabled=true;try{const result=await request(data);if(result.account)activeId=result.account.id;await refresh();message(result.message);return true;}catch(e){message(e.message,true);return false;}finally{busy=false;for(const [el,disabled] of controls)el.disabled=disabled;renderWorkspace();}}\nfunction bindForm(id,handler){const form=$(id);form.addEventListener('submit',e=>{e.preventDefault();handler(form,new FormData(form));});}\nbindForm('accountForm',async(f,d)=>{if(await mutation(f,{action:'create_account',name:d.get('accountName'),cash:d.get('cash'),limitPct:Number(d.get('limitPct'))}))f.elements.accountName.value='';});\nbindForm('savePortfolioForm',(f,d)=>mutation(f,{action:'save_portfolio',name:d.get('snapshotName'),equity,source,positions}));\nbindForm('paperGuardForm',(f,d)=>mutation(f,{action:'set_guard',accountId:activeId,guard:{...Object.fromEntries(guardFields.map(([k])=>[k,Number(d.get(k))])),enabled:d.has('enabled'),paused:d.has('paused')}}));\nbindForm('paperOrderForm',async(f,d)=>{if(!activeId)return;pendingKey=pendingKey||crypto.randomUUID();if(await mutation(f,{action:'order',accountId:activeId,requestId:pendingKey,side:d.get('side'),ticker:d.get('ticker'),sector:d.get('sector'),quantity:Number(d.get('quantity')),price:d.get('price'),fee:d.get('fee')})){pendingKey=null;}});\n// Retain the request ID for retries of an unchanged order, but not a revised order.\n$('paperOrderForm').addEventListener('input',()=>pendingKey=null);\n$('paperAccount').onchange=e=>{activeId=e.target.value;pendingKey=null;renderWorkspace();};$('workspaceRefresh').onclick=refresh;\n$('paperExport').onclick=()=>download('riskpulse-paper-account.json',JSON.stringify({exportedAt:new Date().toISOString(),mode:'Paper simulation; monetary values in USD cents',account:account()},null,2),'application/json');\n$('loadPaperRisk').onclick=()=>{const a=account();if(!a)return;positions=Object.entries(a.holdings).map(([ticker,h])=>({ticker,name:ticker,sector:h.sector,shares:h.quantity,price:h.mark/100,nativePrice:h.mark/100,currency:'USD',fxToUSD:1,side:1,day:0,beta:1,adv:null,cp:'Paper account',credit:'N/A',asOf:h.asOf.slice(0,10),priceSource:'Assumed paper fill'}));equity=(a.cash+Object.values(a.holdings).reduce((s,h)=>s+h.quantity*h.mark,0))/100;source='Paper simulation · '+a.name;$('equityInput').value=equity;render();renderEvidence();show('overview');feedback('Paper holdings loaded. Prices are assumed fills; beta is 1 and ADV is unknown.');};\nrefresh();show('workspace');\n})();\n","type":"text/javascript; charset=utf-8"}};
const SOURCES = {
  fsi: {name:'Office of Financial Research',url:'https://www.financialresearch.gov/financial-stress-index/data/fsi.csv',page:'https://www.financialresearch.gov/financial-stress-index/',cadence:'Daily; normally two business days behind',ttl:3600},
  sofr: {name:'Federal Reserve Bank of New York',url:'https://markets.newyorkfed.org/api/rates/secured/sofr/last/30.json',page:'https://www.newyorkfed.org/markets/reference-rates/sofr',cadence:'Daily reference rate for the effective date',ttl:3600},
  fx: {name:'European Central Bank',url:'https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml',page:'https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html',cadence:'Business-day reference rates; not executable prices',ttl:3600},
  venues: {name:'ISO 10383 Registration Authority',url:'https://www.iso20022.org/sites/default/files/ISO10383_MIC/ISO10383_MIC.csv',page:'https://www.iso20022.org/market-identifier-codes',cadence:'Monthly register; published changes may have future effective dates',ttl:86400}
};
function csvRows(text){
  let rows=[],row=[],field='',quoted=false;
  for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){field+='"';i++}else quoted=false}else field+=c;}
    else if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;
  }if(quoted)throw Error('Malformed source CSV');row.push(field);if(row.some(Boolean))rows.push(row);return rows;
}
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||!Number.isFinite(Date.parse(s)))throw Error('Invalid observation date');return s;}
function numeric(s){if(s===null||s===undefined||String(s).trim()===''||!Number.isFinite(Number(s)))throw Error('Missing or invalid source value');return Number(s);}
function normalize(id,text){
  if(id==='fsi'){
    const [heads,...rows]=csvRows(text);if(heads[0]!=='Date'||!heads.includes('OFR FSI'))throw Error('Unexpected OFR format');
    const history=rows.filter(r=>r.length===heads.length&&r[1]!=='').map(r=>({date:validDate(r[0]),...Object.fromEntries(heads.slice(1).map((h,i)=>[h,numeric(r[i+1])]))})).sort((a,b)=>a.date.localeCompare(b.date)).slice(-252);
    if(history.length<2)throw Error('Insufficient OFR observations');return {asOf:history.at(-1).date,latest:history.at(-1),previous:history.at(-2),history};
  }
  if(id==='sofr'){
    const parsed=JSON.parse(text);if(!Array.isArray(parsed.refRates))throw Error('Unexpected SOFR format');
    const history=parsed.refRates.filter(r=>r.type==='SOFR').map(r=>({date:validDate(r.effectiveDate),rate:numeric(r.percentRate),volumeBillions:numeric(r.volumeInBillions),p1:numeric(r.percentPercentile1),p99:numeric(r.percentPercentile99)})).sort((a,b)=>a.date.localeCompare(b.date));
    if(history.length<2)throw Error('Insufficient SOFR observations');return {asOf:history.at(-1).date,latest:history.at(-1),previous:history.at(-2),history};
  }
  if(id==='fx'){
    const asOf=validDate(text.match(/<Cube\s+time=['"]([^'"]+)['"]/)?.[1]||'');
    const rates=Object.fromEntries([...text.matchAll(/<Cube\s+currency=['"]([A-Z]{3})['"]\s+rate=['"]([\d.]+)['"]/g)].map(m=>[m[1],numeric(m[2])]));
    if(!rates.USD||Object.values(rates).some(x=>x<=0))throw Error('Invalid ECB rate set');return {asOf,base:'EUR',rates:{EUR:1,...rates}};
  }
  if(id==='venues'){
    const [heads,...rows]=csvRows(text);if(!heads.includes('MIC')||!heads.includes('STATUS'))throw Error('Unexpected MIC format');
    const venues=rows.map(r=>{const o=Object.fromEntries(heads.map((h,i)=>[h,r[i]]));return {mic:o.MIC,operatingMic:o['OPERATING MIC'],type:o['OPRT/SGMT'],name:o['MARKET NAME-INSTITUTION DESCRIPTION'],country:o['ISO COUNTRY CODE (ISO 3166)'],city:o.CITY,category:o['MARKET CATEGORY CODE'],status:o.STATUS,updated:o['LAST UPDATE DATE'],created:o['CREATION DATE'],expiry:o['EXPIRY DATE']}}).filter(v=>/^[A-Z0-9]{4}$/.test(v.mic));
    if(!venues.length)throw Error('Empty MIC register');return {venues};
  }throw Error('Unknown source');
}
const memoryCache=new Map();
async function fetchSource(id,fetcher=fetch,clock=()=>Date.now()){
  const spec=SOURCES[id];if(!spec)throw Error('Unknown source');const cached=memoryCache.get(id);
  if(cached&&clock()-cached.time<spec.ttl*1000)return {...cached.data,cached:true};
  const response=await fetcher(spec.url,{headers:{Accept:id==='sofr'?'application/json':'text/*'},signal:AbortSignal.timeout(18000)});
  if(!response.ok)throw Error(`Source returned HTTP ${response.status}`);const text=await response.text();if(text.length>5000000)throw Error('Source response too large');
  const values=normalize(id,text);const now=clock();if(values.asOf&&Date.parse(values.asOf)>now+86400000)throw Error('Source observation is in the future');
  const data={...values,source:spec.name,sourceUrl:spec.page,cadence:spec.cadence,fetchedAt:new Date(now).toISOString(),cached:false};memoryCache.set(id,{time:now,data});return data;
}
async function publicSnapshot(){
  const ids=['fsi','sofr','fx'];const results=await Promise.allSettled(ids.map(id=>fetchSource(id)));
  return {generatedAt:new Date().toISOString(),feeds:Object.fromEntries(ids.map((id,i)=>[id,results[i].status==='fulfilled'?{status:'available',...results[i].value}:{status:'unavailable',source:SOURCES[id].name,sourceUrl:SOURCES[id].page,error:'The upstream source could not be retrieved or validated. Try again later.'}]))};
}

// Public-source requests are fixed allowlisted URLs. No user-supplied proxy URLs.
const headers={'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers});
export default {async fetch(request,env={},ctx={}){
  const url=new URL(request.url);
  if(url.pathname==='/api/workspace')return json({error:'Saved portfolios and paper execution run in the desktop application on your computer. Open http://127.0.0.1:4173 after starting RiskPulse. This hosted dashboard cannot access your local database.'},503);
  if(url.pathname==='/api/licensed/quotes')return json({error:'Licensed quotes require the local desktop edition with Bloomberg or LSEG SDK and an authenticated session. This hosted edition has no vendor credentials.'},503);
  if(!['GET','HEAD'].includes(request.method))return json({error:'Method not allowed'},405);
  try{
    if(url.pathname==='/api/public')return json(await publicSnapshot());
    if(url.pathname==='/api/venues')return json(await fetchSource('venues'));
    if(url.pathname==='/api/status')return json({version:'3.0.0',publicSources:['OFR','New York Fed','ECB','ISO 10383'],licensed:{connected:false,reason:'Exact licensed product, entitlements and deployment constraints have not been configured.'},portfolioStorage:'Browser tab only; no server-side holdings storage',audit:'Downloadable decision snapshot; not a tamper-proof audit service'});
    if(url.pathname.startsWith('/api/'))return json({error:'Not found'},404);
    const path=url.pathname==='/'?'/index.html':url.pathname;const asset=ASSETS[path];
    if(!asset)return new Response('Not found',{status:404});
    return new Response(request.method==='HEAD'?null:asset.body,{headers:{'Content-Type':asset.type,'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Cache-Control':'no-cache','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'"}});
  }catch{return json({error:'Source unavailable or invalid. No synthetic replacement has been supplied.'},502);}
}};
